import React, { useState, useEffect, useRef } from 'react'
import { MessageCircle, X, Send, User, Bot, Loader2 } from 'lucide-react'
import { clsx } from 'clsx'
import { useAuth } from '../context/AuthContext'

export default function Chatbot() {
    const { user, profile } = useAuth()
    const [isOpen, setIsOpen] = useState(false)
    const [messages, setMessages] = useState([
        { role: 'bot', content: 'Hello! I am your CollegeCommunity assistant. How can I help you today?' }
    ])
    const [input, setInput] = useState('')
    const [isThinking, setIsThinking] = useState(false)
    const scrollRef = useRef(null)

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight
        }
    }, [messages, isThinking])

    const handleSendMessage = async (e) => {
        e.preventDefault()
        if (!input.trim() || isThinking) return

        const userMessage = input.trim()
        setInput('')
        setMessages(prev => [...prev, { role: 'user', content: userMessage }])

        setIsThinking(true)

        // Simulate AI "Thinking" and response
        setTimeout(() => {
            let response = "I'm still learning about the college community features. You can post updates, join communities, and check out upcoming events!"

            if (userMessage.toLowerCase().includes('event')) {
                response = "You can find all campus events in the 'Events' tab. faculty members usually post notices there."
            } else if (userMessage.toLowerCase().includes('help')) {
                response = "I can help you navigate the platform. Try looking at the Feed for updates or your Profile to customize your appearance."
            } else if (userMessage.toLowerCase().includes('role')) {
                response = `You are registered as a ${profile?.role || 'student'}. Faculty members have additional permissions to post notices.`
            }

            setMessages(prev => [...prev, { role: 'bot', content: response }])
            setIsThinking(false)
        }, 1500)
    }

    return (
        <div className="fixed bottom-6 right-6 z-50">
            {/* Chatbot Toggle Button */}
            <button
                onClick={() => setIsOpen(!isOpen)}
                className={clsx(
                    "w-14 h-14 rounded-full flex items-center justify-center shadow-2xl transition-all duration-500",
                    isOpen ? "bg-rose-500 rotate-90" : "bg-primary-600 hover:scale-110 shadow-primary-500/30"
                )}
            >
                {isOpen ? <X className="text-white" size={28} /> : <MessageCircle className="text-white" size={28} />}
            </button>

            {/* Chat Window */}
            {isOpen && (
                <div className="absolute bottom-20 right-0 w-[380px] h-[500px] glass-card flex flex-col overflow-hidden animate-in fade-in slide-in-from-bottom-5 duration-300">
                    {/* Header */}
                    <div className="bg-primary-600 p-4 flex items-center gap-3">
                        <div className="w-10 h-10 rounded-xl bg-white/20 flex items-center justify-center">
                            <Bot className="text-white" size={24} />
                        </div>
                        <div>
                            <h3 className="text-white font-bold leading-none">Campus AI</h3>
                            <p className="text-primary-100 text-[10px] mt-1">Always here to help</p>
                        </div>
                    </div>

                    {/* Messages */}
                    <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth">
                        {messages.map((m, i) => (
                            <div key={i} className={clsx("flex", m.role === 'user' ? "justify-end" : "justify-start")}>
                                <div className={clsx(
                                    "max-w-[80%] p-3 rounded-2xl text-sm shadow-sm",
                                    m.role === 'user'
                                        ? "bg-primary-600 text-white rounded-tr-none"
                                        : "bg-[var(--input-bg)] text-[var(--foreground)] border border-[var(--card-border)] rounded-tl-none"
                                )}>
                                    {m.content}
                                </div>
                            </div>
                        ))}
                        {isThinking && (
                            <div className="flex justify-start">
                                <div className="bg-[var(--input-bg)] text-[var(--foreground)] border border-[var(--card-border)] p-3 rounded-2xl rounded-tl-none shadow-sm flex items-center gap-2">
                                    <div className="flex gap-1">
                                        <div className="w-1.5 h-1.5 bg-[var(--text-muted)] rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                                        <div className="w-1.5 h-1.5 bg-[var(--text-muted)] rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                                        <div className="w-1.5 h-1.5 bg-[var(--text-muted)] rounded-full animate-bounce"></div>
                                    </div>
                                    <span className="text-[10px] font-medium text-[var(--text-muted)] uppercase tracking-wider">AI is Thinking</span>
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Input */}
                    <form onSubmit={handleSendMessage} className="p-4 border-t border-[var(--card-border)] bg-[var(--background)] flex gap-2">
                        <input
                            type="text"
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            placeholder="Ask me anything..."
                            className="input-style flex-1 px-4 py-2 text-sm"
                        />
                        <button
                            type="submit"
                            disabled={!input.trim() || isThinking}
                            className="w-10 h-10 bg-primary-600 text-white rounded-xl flex items-center justify-center hover:bg-primary-500 disabled:opacity-50 transition-all"
                        >
                            <Send size={18} />
                        </button>
                    </form>
                </div>
            )}
        </div>
    )
}

import React, { useState, useEffect } from 'react'
import { Outlet, Link, useNavigate, useLocation } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import { useTheme } from '../context/ThemeContext'
import {
    LayoutDashboard, MessageSquare, Calendar, User, LogOut,
    ShieldCheck, Home, Users, Sun, Moon, PackageSearch,
    Building, Trash2, Menu, X, ChevronRight, Bell
} from 'lucide-react'
import { clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'
import Chatbot from './Chatbot'

function cn(...inputs) {
    return twMerge(clsx(inputs))
}

const SidebarLink = ({ to, icon: Icon, label, active, onClick }) => (
    <Link
        to={to}
        onClick={onClick}
        className={cn(
            "flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-300 group",
            active
                ? "bg-primary-600 text-white shadow-lg shadow-primary-600/20"
                : "text-[var(--text-muted)] hover:bg-primary-500/10 hover:text-primary-500"
        )}
    >
        <Icon size={20} className={cn("transition-transform duration-300", active ? "scale-110" : "group-hover:scale-110")} />
        <span className="font-medium flex-1">{label}</span>
        {active && <ChevronRight size={14} className="opacity-50" />}
    </Link>
)

export default function Layout() {
    const { signOut, isAdmin, profile } = useAuth()
    const { theme, toggleTheme } = useTheme()
    const navigate = useNavigate()
    const location = useLocation()
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)

    // Close mobile menu on navigation
    useEffect(() => {
        setIsMobileMenuOpen(false)
    }, [location.pathname])

    const handleLogout = async () => {
        await signOut()
        navigate('/login')
    }

    const menuItems = [
        { to: '/', icon: Home, label: 'Feed' },
        { to: '/forums', icon: Building, label: 'Forums' },
        { to: '/events', icon: Calendar, label: 'Events' },
        { to: '/communities', icon: Users, label: 'Communities' },
        { to: '/lost-found', icon: PackageSearch, label: 'Lost & Found' },
        { to: '/profile', icon: User, label: 'Profile' },
    ]

    if (isAdmin) {
        menuItems.push({ to: '/admin', icon: ShieldCheck, label: 'Admin Panel' })
    }

    const SidebarContent = () => (
        <div className="flex flex-col gap-8 h-full">
            <div className="flex items-center gap-3 px-2">
                <div className="w-10 h-10 bg-primary-600 rounded-xl flex items-center justify-center font-bold text-white text-xl shadow-lg shadow-primary-600/20">
                    C
                </div>
                <span className="text-xl font-bold tracking-tight text-[var(--foreground)]">CollegeCommunity</span>
            </div>

            <nav className="flex-1 flex flex-col gap-2">
                {menuItems.map((item) => (
                    <SidebarLink
                        key={item.to}
                        {...item}
                        active={location.pathname === item.to}
                        onClick={() => setIsMobileMenuOpen(false)}
                    />
                ))}
            </nav>

            <div className="pt-6 border-t border-[var(--card-border)] space-y-2">
                <button
                    onClick={toggleTheme}
                    className="flex items-center gap-3 px-4 py-3 rounded-xl text-[var(--text-muted)] hover:bg-primary-500/10 hover:text-primary-500 transition-all w-full mb-2 group"
                >
                    {theme === 'light' ? <Moon size={20} className="group-hover:rotate-12 transition-transform" /> : <Sun size={20} className="group-hover:rotate-45 transition-transform" />}
                    <span className="font-medium">{theme === 'light' ? 'Dark Mode' : 'Light Mode'}</span>
                </button>
                <button
                    onClick={handleLogout}
                    className="flex items-center gap-3 px-4 py-3 rounded-xl text-[var(--text-muted)] hover:bg-rose-500/10 hover:text-rose-500 transition-all w-full group"
                >
                    <LogOut size={20} className="group-hover:-translate-x-1 transition-transform" />
                    <span className="font-medium">Logout</span>
                </button>
            </div>
        </div>
    )

    return (
        <div className="flex min-h-screen bg-[var(--background)] text-[var(--foreground)] transition-colors duration-400">
            {/* Desktop Sidebar */}
            <aside className="hidden lg:flex w-72 border-r border-[var(--card-border)] p-8 flex-col sticky top-0 h-screen bg-[var(--background)] z-50">
                <SidebarContent />
            </aside>

            {/* Mobile Drawer */}
            <div className={cn(
                "fixed inset-0 bg-black/60 backdrop-blur-sm z-[100] transition-opacity duration-300 lg:hidden",
                isMobileMenuOpen ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none"
            )} onClick={() => setIsMobileMenuOpen(false)}>
                <aside
                    className={cn(
                        "w-72 bg-[var(--background)] h-full p-8 transition-transform duration-500 ease-out",
                        isMobileMenuOpen ? "translate-x-0" : "-translate-x-full"
                    )}
                    onClick={e => e.stopPropagation()}
                >
                    <SidebarContent />
                </aside>
            </div>

            {/* Main Content Area */}
            <div className="flex-1 flex flex-col min-w-0">
                {/* Responsive Header */}
                <header className="sticky top-0 z-40 bg-[var(--background)]/80 backdrop-blur-md border-b border-[var(--card-border)] p-4 lg:p-6 lg:border-none lg:bg-transparent">
                    <div className="max-w-7xl mx-auto flex justify-between items-center">
                        <div className="flex items-center gap-4">
                            <button
                                onClick={() => setIsMobileMenuOpen(true)}
                                className="lg:hidden p-2 hover:bg-[var(--input-bg)] rounded-xl text-[var(--text-muted)] hover:text-[var(--foreground)] transition-colors"
                            >
                                <Menu size={24} />
                            </button>
                            <div className="lg:block">
                                <h1 className="text-xl lg:text-3xl font-bold tracking-tight text-[var(--foreground)] truncate">
                                    {location.pathname === '/' ? 'Home Feed' : location.pathname.split('/')[1].replace('-', ' ')}
                                </h1>
                                <p className="hidden sm:block text-[var(--text-muted)] text-sm font-medium mt-1">
                                    Hello, {profile?.full_name?.split(' ')?.[0] || 'Member'} ΓÇö welcome back!
                                </p>
                            </div>
                        </div>

                        <div className="flex items-center gap-2 lg:gap-6">
                            <button className="p-2.5 text-[var(--text-muted)] hover:text-primary-500 hover:bg-primary-500/10 rounded-xl transition-all relative">
                                <Bell size={20} />
                                <span className="absolute top-2.5 right-2.5 w-2 h-2 bg-primary-500 rounded-full border-2 border-[var(--background)]"></span>
                            </button>

                            <div className="flex items-center gap-3 pl-2 lg:pl-6 border-l border-[var(--card-border)]">
                                <div className="hidden md:block text-right">
                                    <p className="text-sm font-bold text-[var(--foreground)] leading-tight">{profile?.full_name}</p>
                                    <p className="text-[10px] text-[var(--text-muted)] uppercase tracking-wider font-bold mt-0.5">{profile?.role}</p>
                                </div>
                                <Link to="/profile" className="w-10 h-10 lg:w-12 lg:h-12 rounded-2xl bg-[var(--input-bg)] border-2 border-[var(--card-border)] overflow-hidden hover:border-primary-500 transition-colors shadow-sm">
                                    {profile?.avatar_url ? (
                                        <img src={profile.avatar_url} alt="Profile" className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-[var(--text-muted)]">
                                            <User size={20} />
                                        </div>
                                    )}
                                </Link>
                            </div>
                        </div>
                    </div>
                </header>

                <main className="flex-1 px-4 py-6 lg:p-8 max-w-7xl mx-auto w-full animate-fade-in">
                    <Outlet />
                </main>
                <Chatbot />
            </div>
        </div>
    )
}

import React, { createContext, useContext, useEffect, useState } from 'react'
import { supabase } from '../lib/supabase'

const AuthContext = createContext({})

export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null)
    const [profile, setProfile] = useState(null)
    const [loading, setLoading] = useState(true)

    useEffect(() => {
        // Check active session
        supabase.auth.getSession().then(({ data: { session } }) => {
            setUser(session?.user ?? null)
            if (session?.user) fetchProfile(session.user.id)
            else setLoading(false)
        })

        // Listen for auth changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            setUser(session?.user ?? null)
            if (session?.user) fetchProfile(session.user.id)
            else {
                setProfile(null)
                setLoading(false)
            }
        })

        return () => subscription.unsubscribe()
    }, [])

    const fetchProfile = async (userId) => {
        const { data, error } = await supabase
            .from('profiles')
            .select('*')
            .eq('id', userId)
            .single()

        if (error) console.error('Error fetching profile:', error)
        else setProfile(data)
        setLoading(false)
    }

    const value = {
        signUp: (data) => supabase.auth.signUp(data),
        signIn: (data) => supabase.auth.signInWithPassword(data),
        signOut: () => supabase.auth.signOut(),
        user,
        profile,
        loading,
        isAdmin: profile?.role === 'admin',
        isFaculty: profile?.role === 'faculty',
        refreshProfile: () => user && fetchProfile(user.id)
    }

    return (
        <AuthContext.Provider value={value}>
            {!loading && children}
        </AuthContext.Provider>
    )
}

export const useAuth = () => useContext(AuthContext)

import React, { createContext, useContext, useEffect, useState } from 'react';

const ThemeContext = createContext();

export const ThemeProvider = ({ children }) => {
    const [theme, setTheme] = useState(localStorage.getItem('theme') || 'dark');

    useEffect(() => {
        const root = window.document.documentElement;
        root.classList.remove('light', 'dark');
        root.classList.add(theme);
        localStorage.setItem('theme', theme);
    }, [theme]);

    const toggleTheme = () => {
        setTheme((prev) => (prev === 'light' ? 'dark' : 'light'));
    };

    return (
        <ThemeContext.Provider value={{ theme, toggleTheme }}>
            {children}
        </ThemeContext.Provider>
    );
};

export const useTheme = () => {
    const context = useContext(ThemeContext);
    if (context === undefined) {
        throw new Error('useTheme must be used within a ThemeProvider');
    }
    return context;
};

import React, { useState, useEffect } from 'react'
import { useAuth } from '../context/AuthContext'
import { supabase } from '../lib/supabase'
import { Users, Plus, UserPlus, UserMinus, Loader2, Search, Trash2, X } from 'lucide-react'
import { moderateContent } from '../utils/moderation'
import { clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

function cn(...inputs) {
    return twMerge(clsx(inputs))
}

export default function Communities() {
    const { user, profile, isAdmin } = useAuth()
    const [communities, setCommunities] = useState([])
    const [myMemberships, setMyMemberships] = useState([])
    const [loading, setLoading] = useState(true)
    const [showModal, setShowModal] = useState(false)
    const [search, setSearch] = useState('')

    const [name, setName] = useState('')
    const [description, setDescription] = useState('')
    const [department, setDepartment] = useState('')

    useEffect(() => {
        fetchCommunities()
        fetchMyMemberships()

        const channel = supabase
            .channel('communities-realtime')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'communities' }, () => fetchCommunities())
            .on('postgres_changes', { event: '*', schema: 'public', table: 'community_members' }, () => {
                fetchCommunities()
                fetchMyMemberships()
            })
            .subscribe()

        return () => { supabase.removeChannel(channel) }
    }, [])

    const fetchCommunities = async () => {
        const { data, error } = await supabase
            .from('communities')
            .select('*, profiles(full_name), community_members(count)')
            .order('created_at', { ascending: false })

        if (error) console.error(error)
        else setCommunities(data)
        setLoading(false)
    }

    const fetchMyMemberships = async () => {
        const { data } = await supabase
            .from('community_members')
            .select('community_id')
            .eq('user_id', user.id)

        if (data) setMyMemberships(data.map(m => m.community_id))
    }

    const handleCreate = async (e) => {
        e.preventDefault()
        setLoading(true)

        try {
            // Moderate name and description
            const contentToModerate = `${name} ${description} `
            const result = await moderateContent(contentToModerate, 'community', user.id)
            if (result.flagged) {
                alert('≡ƒÜ½ Community creation blocked by AI. The name or description contains inappropriate content.')
                setLoading(false)
                return
            }

            const { data, error } = await supabase.from('communities').insert({
                name,
                description,
                department,
                creator_id: user.id
            }).select().single()

            if (error) throw error

            // Auto-join the community you created
            await supabase.from('community_members').insert({
                community_id: data.id,
                user_id: user.id
            })

            setShowModal(false)
            setName(''); setDescription(''); setDepartment('')
        } catch (err) {
            alert(err.message)
        } finally {
            setLoading(false)
        }
    }

    const handleDelete = async (id) => {
        if (!window.confirm('Are you sure you want to delete this community?')) return
        const { error } = await supabase.from('communities').delete().eq('id', id)
        if (error) alert('Failed to delete community: ' + error.message)
        else fetchCommunities()
    }

    const handleJoin = async (communityId) => {
        const { error } = await supabase.from('community_members').insert({
            community_id: communityId,
            user_id: user.id
        })
        if (error) alert(error.message)
    }

    const handleLeave = async (communityId) => {
        const { error } = await supabase
            .from('community_members')
            .delete()
            .eq('community_id', communityId)
            .eq('user_id', user.id)
        if (error) alert(error.message)
    }

    const isMember = (communityId) => myMemberships.includes(communityId)

    const filtered = communities.filter(c =>
        c.name.toLowerCase().includes(search.toLowerCase()) ||
        c.description?.toLowerCase().includes(search.toLowerCase())
    )

    return (
        <div className="space-y-10 max-w-7xl mx-auto">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
                <div>
                    <h2 className="text-3xl lg:text-4xl font-extrabold text-[var(--foreground)] tracking-tight">Communities</h2>
                    <p className="text-[var(--text-muted)] mt-1 font-medium italic">Join groups and connect with peers</p>
                </div>
                {(profile?.role === 'faculty' || profile?.role === 'student' || isAdmin) && (
                    <button
                        onClick={() => setShowModal(true)}
                        className="w-full sm:w-auto flex items-center justify-center gap-2.5 bg-primary-600 hover:bg-primary-500 text-white px-8 py-4 rounded-2xl font-black transition-all shadow-2xl shadow-primary-600/30 active:scale-[0.98]"
                    >
                        <Plus size={20} className="stroke-[3]" />
                        <span>Create Community</span>
                    </button>
                )}
            </div>

            {/* Search */}
            <div className="relative group animate-fade-in">
                <Search size={22} className="absolute left-5 top-1/2 -translate-y-1/2 text-[var(--text-muted)] group-focus-within:text-primary-500 transition-colors" />
                <input
                    type="text"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    placeholder="Search by community name or focus..."
                    className="input-style w-full pl-14 pr-6 py-4.5 text-lg shadow-sm"
                />
            </div>

            {loading ? (
                <div className="flex items-center justify-center p-20">
                    <Loader2 className="text-primary-500 animate-spin" size={48} />
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 lg:gap-8">
                    {filtered.map((community) => {
                        const memberCount = community.community_members?.[0]?.count || 0
                        const joined = isMember(community.id)

                        return (
                            <div key={community.id} className="glass-card bg-[var(--card-bg)] border-[var(--card-border)] hover:border-primary-500 transition-all overflow-hidden group flex flex-col">
                                <div className="h-32 bg-gradient-to-br from-primary-600/10 to-primary-900/30 relative flex items-center justify-center overflow-hidden">
                                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,rgba(255,255,255,0.05),transparent)]" />
                                    <Users size={48} className="text-primary-500 opacity-20 group-hover:scale-110 transition-transform duration-500" />
                                    {community.department && (
                                        <div className="absolute top-4 right-4">
                                            <span className="text-[10px] bg-white/10 backdrop-blur-md text-white px-3 py-1.5 rounded-lg font-black uppercase tracking-tighter border border-white/10">
                                                {community.department}
                                            </span>
                                        </div>
                                    )}
                                </div>
                                <div className="p-6 space-y-5 flex-1 flex flex-col">
                                    <div className="flex-1">
                                        <h3 className="text-xl lg:text-2xl font-black text-[var(--foreground)] group-hover:text-primary-600 transition-colors line-clamp-1">{community.name}</h3>
                                        <p className="text-[var(--text-muted)] text-sm mt-2 line-clamp-3 leading-relaxed font-medium">{community.description}</p>
                                    </div>

                                    <div className="flex items-center justify-between pt-5 border-t border-[var(--card-border)] mt-auto">
                                        <div className="flex items-center gap-2 text-[var(--text-muted)] font-black text-xs uppercase tracking-widest">
                                            <Users size={16} className="text-primary-500" />
                                            <span>{memberCount} members</span>
                                        </div>

                                        {joined ? (
                                            <button
                                                onClick={() => handleLeave(community.id)}
                                                className="flex items-center gap-2 text-xs font-black text-rose-500 hover:bg-rose-500/10 px-4 py-2.5 rounded-xl transition-all border border-rose-500/10 uppercase tracking-widest"
                                            >
                                                <UserMinus size={16} /> <span>Leave</span>
                                            </button>
                                        ) : (
                                            <button
                                                onClick={() => handleJoin(community.id)}
                                                className="flex items-center gap-2 text-xs font-black text-primary-600 bg-primary-500/10 hover:bg-primary-600 hover:text-white px-4 py-2.5 rounded-xl transition-all border border-primary-500/10 uppercase tracking-widest"
                                            >
                                                <UserPlus size={16} /> <span>Join Group</span>
                                            </button>
                                        )}
                                    </div>

                                    {(isAdmin || community.creator_id === user.id) && (
                                        <div className="pt-2 flex justify-end">
                                            <button
                                                onClick={() => handleDelete(community.id)}
                                                className="p-2.5 bg-rose-500/5 hover:bg-rose-500 text-rose-500 hover:text-white rounded-xl transition-all border border-rose-500/10 group/del"
                                                title="Delete Community"
                                            >
                                                <Trash2 size={18} className="group-hover/del:scale-110 transition-transform" />
                                            </button>
