                </div>
            )}
        </div>
    )
}

import React, { useState, useEffect } from 'react'
import { useAuth } from '../context/AuthContext'
import { supabase } from '../lib/supabase'
import { Calendar, MapPin, Plus, Loader2, Clock, Users, Trash2, X } from 'lucide-react'
import { clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

function cn(...inputs) {
    return twMerge(clsx(inputs))
}

export default function Events() {
    const { user, isAdmin } = useAuth()
    const [events, setEvents] = useState([])
    const [loading, setLoading] = useState(true)
    const [showModal, setShowModal] = useState(false)

    const [title, setTitle] = useState('')
    const [description, setDescription] = useState('')
    const [date, setDate] = useState('')
    const [location, setLocation] = useState('')
    const [department, setDepartment] = useState('')

    useEffect(() => {
        fetchEvents()

        // Real-time subscription
        const channel = supabase
            .channel('events-realtime')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'events' }, () => {
                fetchEvents()
            })
            .subscribe()

        return () => { supabase.removeChannel(channel) }
    }, [])

    const fetchEvents = async () => {
        const { data, error } = await supabase
            .from('events')
            .select('*, profiles(full_name)')
            .order('event_date', { ascending: true })

        if (error) console.error(error)
        else setEvents(data)
        setLoading(false)
    }

    const handleCreate = async (e) => {
        e.preventDefault()
        setLoading(true)

        try {
            const { error } = await supabase.from('events').insert({
                creator_id: user.id,
                title,
                description,
                event_date: date,
                location,
                department
            })

            if (error) alert(error.message)
            else {
                setShowModal(false)
                setTitle(''); setDescription(''); setDate(''); setLocation(''); setDepartment('')
            }
        } finally {
            setLoading(false)
        }
    }

    const handleDelete = async (id) => {
        if (!window.confirm('Are you sure you want to delete this event?')) return
        const { error } = await supabase.from('events').delete().eq('id', id)
        if (error) alert('Failed to delete event: ' + error.message)
        else fetchEvents()
    }

    const upcomingEvents = events.filter(e => new Date(e.event_date) > new Date())
    const pastEvents = events.filter(e => new Date(e.event_date) <= new Date())

    return (
        <div className="space-y-10 max-w-7xl mx-auto">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
                <div>
                    <h2 className="text-3xl lg:text-4xl font-extrabold text-[var(--foreground)] tracking-tight">Campus Events</h2>
                    <p className="text-[var(--text-muted)] mt-1 font-medium italic">Discover what's happening around the college</p>
                </div>
                {isAdmin && (
                    <button
                        onClick={() => setShowModal(true)}
                        className="w-full sm:w-auto flex items-center justify-center gap-2.5 bg-primary-600 hover:bg-primary-500 text-white px-8 py-4 rounded-2xl font-black transition-all shadow-2xl shadow-primary-600/30 active:scale-[0.98]"
                    >
                        <Plus size={20} className="stroke-[3]" />
                        <span>Create Event</span>
                    </button>
                )}
            </div>

            {loading ? (
                <div className="flex items-center justify-center p-20">
                    <Loader2 className="text-primary-500 animate-spin" size={48} />
                </div>
            ) : (
                <>
                    {/* Upcoming Events */}
                    {upcomingEvents.length > 0 && (
                        <div>
                            <div className="flex items-center gap-3 mb-6">
                                <div className="w-1.5 h-6 bg-emerald-500 rounded-full"></div>
                                <h3 className="text-xl font-black text-[var(--foreground)] flex items-center gap-2 uppercase tracking-widest text-sm">
                                    Upcoming Events
                                </h3>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 lg:gap-8">
                                {upcomingEvents.map((event) => (
                                    <EventCard key={event.id} event={event} upcoming isAdmin={isAdmin} user={user} handleDelete={handleDelete} />
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Past Events */}
                    {pastEvents.length > 0 && (
                        <div>
                            <div className="flex items-center gap-3 mb-6 opacity-60">
                                <div className="w-1.5 h-6 bg-slate-500 rounded-full"></div>
                                <h3 className="text-xl font-black text-[var(--foreground)] flex items-center gap-2 uppercase tracking-widest text-sm">
                                    Past Events
                                </h3>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 lg:gap-8">
                                {pastEvents.map((event) => (
                                    <EventCard key={event.id} event={event} isAdmin={isAdmin} user={user} handleDelete={handleDelete} />
                                ))}
                            </div>
                        </div>
                    )}

                    {events.length === 0 && (
                        <div className="text-center p-20 glass-card bg-slate-900/50 border-dashed border-slate-800">
                            <Calendar size={48} className="mx-auto text-slate-600 mb-4" />
                            <p className="text-slate-500">No events yet. Faculty can create new events!</p>
                        </div>
                    )}
                </>
            )}

            {/* Create Event Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[100] flex items-center justify-center p-4 lg:p-6 animate-fade-in">
                    <div className="glass-card bg-[var(--card-bg)] border-[var(--card-border)] w-full max-w-xl p-6 lg:p-10 shadow-[0_32px_64px_-16px_rgba(0,0,0,0.3)] overflow-y-auto max-h-[90vh]">
                        <div className="flex justify-between items-center mb-8">
                            <div>
                                <h3 className="text-2xl lg:text-3xl font-black text-[var(--foreground)] tracking-tight">Create Event</h3>
                                <p className="text-[var(--text-muted)] text-sm font-medium mt-1">Host a new community gathering</p>
                            </div>
                            <button onClick={() => setShowModal(false)} className="p-2 text-[var(--text-muted)] hover:text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all">
                                <X size={24} />
                            </button>
                        </div>

                        <form onSubmit={handleCreate} className="space-y-6">
                            <div className="space-y-2">
                                <label className="text-[11px] font-black text-primary-600 uppercase tracking-widest pl-1">Event Title</label>
                                <input
                                    required
                                    value={title}
                                    onChange={(e) => setTitle(e.target.value)}
                                    className="input-style w-full px-5 py-4"
                                    placeholder="e.g. Annual Tech Symposium"
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[11px] font-black text-primary-600 uppercase tracking-widest pl-1">Department / Organization</label>
                                <input
                                    value={department}
                                    onChange={(e) => setDepartment(e.target.value)}
                                    className="input-style w-full px-5 py-4"
                                    placeholder="e.g. Mechanical Engineering"
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-[11px] font-black text-primary-600 uppercase tracking-widest pl-1">Description</label>
                                <textarea
                                    required
                                    value={description}
                                    onChange={(e) => setDescription(e.target.value)}
                                    className="input-style w-full px-5 py-4 h-32 resize-none"
                                    placeholder="What's happening at this event?"
                                />
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div className="space-y-2">
                                    <label className="text-[11px] font-black text-primary-600 uppercase tracking-widest pl-1">Schedule</label>
                                    <input
                                        type="datetime-local"
                                        required
                                        value={date}
                                        onChange={(e) => setDate(e.target.value)}
                                        className="input-style w-full px-5 py-4"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[11px] font-black text-primary-600 uppercase tracking-widest pl-1">Venue</label>
                                    <input
                                        required
                                        value={location}
                                        onChange={(e) => setLocation(e.target.value)}
                                        className="input-style w-full px-5 py-4"
                                        placeholder="Main Auditorium"
                                    />
                                </div>
                            </div>
                            <div className="flex gap-4 pt-4">
                                <button
                                    type="button"
                                    onClick={() => setShowModal(false)}
                                    className="flex-1 bg-[var(--input-bg)] hover:bg-slate-200 dark:hover:bg-slate-800 text-[var(--foreground)] font-bold py-4 rounded-2xl transition-all border border-[var(--input-border)]"
                                >
                                    Discard
                                </button>
                                <button
                                    type="submit"
                                    className="flex-2 bg-primary-600 hover:bg-primary-500 text-white font-black py-4 rounded-2xl shadow-xl shadow-primary-600/30 transition-all active:scale-[0.98]"
                                >
                                    Publish Event
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    )
}

function EventCard({ event, upcoming, isAdmin, user, handleDelete }) {
    return (
        <div className={cn(
            "glass-card bg-[var(--card-bg)] border-[var(--card-border)] group hover:border-primary-500 transition-all overflow-hidden flex flex-col",
            !upcoming && "opacity-60 saturate-50 hover:opacity-100 hover:saturate-100"
        )}>
            <div className="h-40 bg-gradient-to-br from-primary-600/20 to-primary-900/40 relative overflow-hidden">
                <div className="absolute inset-0 bg-[radial-gradient(circle_at_20%_20%,rgba(255,255,255,0.1),transparent)]" />
                <div className="absolute inset-0 bg-gradient-to-t from-[var(--card-bg)] to-transparent" />

                <div className="absolute top-4 left-4 flex gap-2">
                    <span className={cn(
                        "text-[10px] text-white font-black uppercase px-3 py-1.5 rounded-lg shadow-lg",
                        upcoming ? "bg-emerald-500 shadow-emerald-500/20" : "bg-slate-500 shadow-slate-500/20"
                    )}>
                        {upcoming ? 'Live Update' : 'Concluded'}
                    </span>
                    {event.department && (
                        <span className="text-[10px] bg-white/10 backdrop-blur-md text-white px-3 py-1.5 rounded-lg font-black uppercase tracking-tighter border border-white/10">
                            {event.department}
                        </span>
                    )}
                </div>

                <div className="absolute bottom-4 left-6 right-6">
                    <h3 className="text-xl lg:text-2xl font-black text-[var(--foreground)] group-hover:text-primary-600 transition-colors line-clamp-1 truncate drop-shadow-sm">
                        {event.title}
                    </h3>
                </div>
            </div>

            <div className="p-6 space-y-5 flex-1 flex flex-col">
                <p className="text-[var(--text-muted)] text-sm leading-relaxed line-clamp-3 font-medium">
                    {event.description}
                </p>

                <div className="space-y-3 pt-4 border-t border-[var(--card-border)] mt-auto">
                    <div className="flex items-center gap-3 text-sm font-bold text-[var(--foreground)]">
                        <div className="w-8 h-8 rounded-xl bg-primary-500/10 flex items-center justify-center text-primary-500">
                            <Calendar size={18} />
                        </div>
                        <div className="flex flex-col">
                            <span className="text-xs text-[var(--text-muted)] uppercase tracking-widest font-black">Date</span>
                            <span>{new Date(event.event_date).toLocaleDateString([], { month: 'long', day: 'numeric', year: 'numeric' })}</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 text-sm font-bold text-[var(--foreground)]">
                        <div className="w-8 h-8 rounded-xl bg-rose-500/10 flex items-center justify-center text-rose-500">
                            <MapPin size={18} />
                        </div>
                        <div className="flex flex-col">
                            <span className="text-xs text-[var(--text-muted)] uppercase tracking-widest font-black">Location</span>
                            <span className="line-clamp-1">{event.location}</span>
                        </div>
                    </div>
                </div>

                <div className="pt-5 border-t border-[var(--card-border)] flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-9 h-9 rounded-2xl bg-[var(--input-bg)] border border-[var(--card-border)] flex items-center justify-center text-xs text-[var(--text-muted)] font-black uppercase shadow-sm">
                            {event.profiles?.full_name?.charAt(0) || '?'}
                        </div>
                        <div className="flex flex-col">
                            <span className="text-[10px] text-[var(--text-muted)] uppercase tracking-widest font-black leading-none">Organizer</span>
                            <span className="text-xs font-bold text-[var(--foreground)] mt-1">{event.profiles?.full_name}</span>
                        </div>
                    </div>

                    {(isAdmin || event.creator_id === user.id) && (
                        <button
                            onClick={() => handleDelete(event.id)}
                            className="p-2.5 bg-rose-500/5 hover:bg-rose-500 text-rose-500 hover:text-white rounded-xl transition-all border border-rose-500/20 group/del shadow-sm hover:shadow-rose-500/30"
                            title="Delete Event"
                        >
                            <Trash2 size={18} className="transition-transform group-hover/del:scale-110" />
                        </button>
                    )}
                </div>
            </div>
        </div>
    )
}

import React, { useState, useEffect, useRef } from 'react'
import { Plus, Send, Image as ImageIcon, MessageCircle, Heart, Share2, MoreVertical, Bell, X, Loader2, ShieldCheck } from 'lucide-react'
import { moderateContent } from '../utils/moderation'
import { useAuth } from '../context/AuthContext'
import { supabase } from '../lib/supabase'

export default function Feed() {
    const { user, profile } = useAuth()
    const [content, setContent] = useState('')
    const [loading, setLoading] = useState(false)
    const [posts, setPosts] = useState([])
    const [notices, setNotices] = useState([])
    const [message, setMessage] = useState(null)
    const [imageFile, setImageFile] = useState(null)
    const [imagePreview, setImagePreview] = useState(null)
    const [likes, setLikes] = useState({})       // { postId: count }
    const [myLikes, setMyLikes] = useState({})    // { postId: true }
    const [comments, setComments] = useState({})  // { postId: [comments] }
    const [openComments, setOpenComments] = useState({}) // { postId: true }
    const [commentText, setCommentText] = useState({})   // { postId: text }
    const fileInputRef = useRef(null)

    useEffect(() => {
        fetchPosts()
        fetchNotices()

        const channel = supabase
            .channel('feed-realtime')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'posts' }, () => fetchPosts())
            .on('postgres_changes', { event: '*', schema: 'public', table: 'likes' }, () => fetchAllLikes())
            .on('postgres_changes', { event: '*', schema: 'public', table: 'comments' }, () => fetchAllComments())
            .subscribe()

        return () => { supabase.removeChannel(channel) }
    }, [])

    const fetchPosts = async () => {
        const { data } = await supabase
            .from('posts')
            .select('*, profiles(full_name, avatar_url, role)')
            .eq('status', 'approved')
            .order('created_at', { ascending: false })

        if (data) {
            setPosts(data)
            // Fetch likes and comments for these posts
            fetchAllLikes()
            fetchAllComments()
        }
    }

    const fetchAllLikes = async () => {
        const { data } = await supabase.from('likes').select('post_id, user_id')
        if (data) {
            const counts = {}
            const mine = {}
            data.forEach(l => {
                counts[l.post_id] = (counts[l.post_id] || 0) + 1
                if (l.user_id === user.id) mine[l.post_id] = true
            })
            setLikes(counts)
            setMyLikes(mine)
        }
    }

    const fetchAllComments = async () => {
        const { data } = await supabase
            .from('comments')
            .select('*, profiles(full_name, avatar_url)')
            .order('created_at', { ascending: true })
        if (data) {
            const grouped = {}
            data.forEach(c => {
                if (!grouped[c.post_id]) grouped[c.post_id] = []
                grouped[c.post_id].push(c)
            })
            setComments(grouped)
        }
    }

    const fetchNotices = async () => {
        const { data } = await supabase.from('events').select('*').order('event_date', { ascending: true }).limit(3)
        if (data) setNotices(data)
    }

    const handleLike = async (postId) => {
        if (myLikes[postId]) {
            await supabase.from('likes').delete().eq('post_id', postId).eq('user_id', user.id)
        } else {
            await supabase.from('likes').insert({ post_id: postId, user_id: user.id })
        }
    }

    const handleComment = async (postId) => {
        const text = commentText[postId]?.trim()
        if (!text) return

        try {
            // Moderate comment
            const result = await moderateContent(text, 'comment', user.id)
            if (result.flagged) {
                alert('≡ƒÜ½ Comment blocked by AI. It contains inappropriate content.')
                return
            }
        } catch (e) {
            // If moderation fails, allow comment (fail-open for comments)
        }

        await supabase.from('comments').insert({
            post_id: postId,
            user_id: user.id,
            content: text,
            status: 'approved'
        })
        setCommentText(prev => ({ ...prev, [postId]: '' }))
    }

    const handleImageSelect = (e) => {
        const file = e.target.files[0]
        if (!file) return
        if (file.size > 5 * 1024 * 1024) { setMessage({ type: 'error', text: 'Image must be less than 5MB' }); return }
        setImageFile(file)
        setImagePreview(URL.createObjectURL(file))
    }

    const uploadImage = async (file) => {
        const fileExt = file.name.split('.').pop()
        const fileName = `${user.id}-${Date.now()}.${fileExt}`
        const { error } = await supabase.storage.from('post-images').upload(fileName, file)
        if (error) throw error
        const { data: { publicUrl } } = supabase.storage.from('post-images').getPublicUrl(fileName)
        return publicUrl
    }

    const handleSubmit = async (e) => {
        e.preventDefault()
        if (!content.trim() && !imageFile) return
        setLoading(true)
        setMessage(null)

        try {
            if (content.trim()) {
                const result = await moderateContent(content, 'post', user.id)
                console.log('Moderation result:', result)
                if (result.flagged) {
                    alert('≡ƒÜ½ Content flagged as inappropriate by AI. Post rejected.')
                    setLoading(false)
                    return
                }
            }

            let imageUrl = null
            if (imageFile) imageUrl = await uploadImage(imageFile)

            const { error } = await supabase.from('posts').insert({
                user_id: user.id,
                content: content || '≡ƒô╖ Shared an image',
                image_url: imageUrl,
                status: 'approved'
            })
            if (error) throw error

            setContent('')
            setImageFile(null)
            setImagePreview(null)
            setMessage({ type: 'success', text: 'Γ£à Post published!' })
        } catch (error) {
            setMessage({ type: 'error', text: error.message })
        } finally {
            setLoading(false)
        }
    }

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-8 lg:items-start">
            <div className="lg:col-span-2 space-y-6">
                {/* Create Post */}
                <div className="glass-card p-4 lg:p-6 bg-slate-900 border-slate-800 shadow-xl overflow-hidden">
                    <form onSubmit={handleSubmit}>
                        <div className="flex gap-4">
                            <div className="w-10 h-10 lg:w-12 lg:h-12 rounded-2xl bg-slate-800 flex-shrink-0 flex items-center justify-center text-slate-500 overflow-hidden border border-slate-700">
                                {profile?.avatar_url ? <img src={profile.avatar_url} alt="Me" className="w-full h-full object-cover" /> : <Plus size={20} />}
                            </div>
                            <textarea
                                value={content}
                                onChange={(e) => setContent(e.target.value)}
                                placeholder="What's happening on campus?"
                                className="w-full bg-slate-800/20 border border-slate-700/30 rounded-2xl p-4 text-white focus:outline-none focus:ring-2 focus:ring-primary-500/50 transition-all resize-none h-32 text-sm lg:text-base"
                            />
                        </div>

                        {imagePreview && (
                            <div className="relative mt-4 ml-0 lg:ml-16">
                                <div className="rounded-2xl overflow-hidden border border-slate-700 aspect-video lg:aspect-auto">
                                    <img src={imagePreview} alt="Preview" className="w-full h-full object-cover max-h-64" />
                                </div>
                                <button type="button" onClick={() => { setImageFile(null); setImagePreview(null) }} className="absolute top-2 right-2 bg-black/60 backdrop-blur-md text-white p-2 rounded-full hover:bg-rose-500 transition-all shadow-lg">
                                    <X size={16} />
                                </button>
                            </div>
                        )}

                        {message && (
                            <div className={cn(
                                "mt-4 p-3 rounded-xl border flex items-center gap-2 text-sm ml-0 lg:ml-16 animate-fade-in",
                                message.type === 'error' ? "bg-rose-500/10 text-rose-500 border-rose-500/20" : "bg-emerald-500/10 text-emerald-500 border-emerald-500/20"
                            )}>
                                <div className={cn("w-1.5 h-1.5 rounded-full", message.type === 'error' ? "bg-rose-500" : "bg-emerald-500")}></div>
                                {message.text}
                            </div>
                        )}

                        <div className="flex flex-col sm:flex-row justify-between items-center mt-6 gap-4 ml-0 lg:ml-16">
                            <div className="flex gap-2 w-full sm:w-auto">
                                <input type="file" ref={fileInputRef} onChange={handleImageSelect} accept="image/*" className="hidden" />
                                <button type="button" onClick={() => fileInputRef.current?.click()} className="flex-1 sm:flex-none py-2.5 px-4 bg-slate-800/50 hover:bg-slate-800 text-slate-300 hover:text-white rounded-xl transition-all flex items-center justify-center gap-2 border border-slate-700/50">
                                    <ImageIcon size={18} className="text-primary-500" />
                                    <span className="text-sm font-semibold">Photo</span>
                                </button>
                            </div>
                            <button disabled={loading || (!content.trim() && !imageFile)} className="w-full sm:w-auto bg-primary-600 hover:bg-primary-500 disabled:opacity-50 text-white px-8 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition-all shadow-lg shadow-primary-600/30">
                                {loading ? <><Loader2 size={18} className="animate-spin" /> Analyzing...</> : <>Post <Send size={18} /></>}
                            </button>
                        </div>
                    </form>
                </div>

                {/* Posts */}
                <div className="space-y-6">
                    {posts.map((post) => (
                        <div key={post.id} className="glass-card p-5 lg:p-6 bg-slate-900 border-slate-800 hover:border-slate-700/50 transition-all shadow-sm">
                            {/* Post Header */}
                            <div className="flex justify-between items-start mb-4">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 lg:w-11 lg:h-11 rounded-1.5xl bg-slate-800 overflow-hidden border border-slate-700/50 flex items-center justify-center text-slate-500 font-bold">
                                        {post.profiles?.avatar_url ? <img src={post.profiles.avatar_url} alt="" className="w-full h-full object-cover" /> : (post.profiles?.full_name?.charAt(0) || 'U')}
                                    </div>
                                    <div>
                                        <h4 className="text-sm font-bold text-white flex items-center gap-2">
                                            {post.profiles?.full_name}
                                            {post.profiles?.role === 'faculty' && <span className="bg-primary-600/20 text-primary-400 text-[9px] px-2 py-0.5 rounded-full border border-primary-500/20 font-black tracking-widest uppercase">Faculty</span>}
                                        </h4>
                                        <p className="text-[10px] text-slate-500 font-medium">{new Date(post.created_at).toLocaleDateString([], { month: 'short', day: 'numeric' })} ΓÇó {new Date(post.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                                    </div>
                                </div>
                                <button className="p-2 text-slate-500 hover:text-white transition-colors">
                                    <MoreVertical size={16} />
                                </button>
                            </div>

                            {/* Post Content */}
                            <div className="text-slate-200 text-sm lg:text-[15px] leading-relaxed mb-4 whitespace-pre-wrap">{post.content}</div>
                            {post.image_url && (
                                <div className="mb-4 rounded-2xl overflow-hidden border border-slate-800/50 bg-slate-800/30">
                                    <img src={post.image_url} alt="Post" className="w-full h-auto object-cover max-h-[500px]" />
                                </div>
                            )}

                            {/* Like & Comment Buttons */}
                            <div className="flex items-center gap-4 lg:gap-8 pt-4 border-t border-slate-800/40">
                                <button
                                    onClick={() => handleLike(post.id)}
                                    className={`flex items-center gap-2.5 text-xs font-bold transition-all py-1.5 ${myLikes[post.id] ? 'text-rose-500' : 'text-slate-400 hover:text-rose-500'}`}
                                >
                                    <Heart size={20} fill={myLikes[post.id] ? 'currentColor' : 'none'} className={cn("transition-transform", myLikes[post.id] && "scale-110")} />
                                    <span>{likes[post.id] || 0}</span>
                                </button>
                                <button
                                    onClick={() => setOpenComments(prev => ({ ...prev, [post.id]: !prev[post.id] }))}
                                    className="flex items-center gap-2.5 text-xs font-bold text-slate-400 hover:text-primary-500 transition-all py-1.5"
                                >
                                    <MessageCircle size={20} />
                                    <span>{(comments[post.id]?.length || 0)}</span>
                                </button>
                                <button className="flex items-center gap-2.5 text-xs font-bold text-slate-400 hover:text-primary-500 transition-all py-1.5 ml-auto">
                                    <Share2 size={18} />
                                </button>
                            </div>

                            {/* Comments Section */}
                            {openComments[post.id] && (
                                <div className="mt-4 pt-4 border-t border-slate-800/40 space-y-4 animate-fade-in">
                                    <div className="space-y-3 max-h-64 overflow-y-auto pr-2 custom-scrollbar">
                                        {(comments[post.id] || []).map(c => (
                                            <div key={c.id} className="flex items-start gap-3">
                                                <div className="w-8 h-8 rounded-xl bg-slate-800 flex items-center justify-center text-[10px] text-slate-400 font-bold flex-shrink-0 overflow-hidden border border-slate-700/50">
                                                    {c.profiles?.avatar_url ? <img src={c.profiles.avatar_url} alt="" className="w-full h-full object-cover" /> : (c.profiles?.full_name?.charAt(0) || '?')}
                                                </div>
                                                <div className="bg-slate-800/40 rounded-2xl px-4 py-2.5 flex-1 border border-slate-700/30">
                                                    <div className="flex justify-between items-center mb-1">
                                                        <p className="text-[11px] font-bold text-white">{c.profiles?.full_name}</p>
                                                        <span className="text-[9px] text-slate-500">{new Date(c.created_at).toLocaleDateString()}</span>
                                                    </div>
                                                    <p className="text-sm text-slate-300 leading-snug">{c.content}</p>
                                                </div>
                                            </div>
                                        ))}
                                    </div>

                                    {/* Add Comment */}
                                    <div className="flex items-center gap-2 bg-slate-800/30 p-2 rounded-2xl border border-slate-700/30">
                                        <input
                                            type="text"
                                            value={commentText[post.id] || ''}
                                            onChange={(e) => setCommentText(prev => ({ ...prev, [post.id]: e.target.value }))}
                                            onKeyDown={(e) => e.key === 'Enter' && handleComment(post.id)}
                                            placeholder="Write a community response..."
                                            className="flex-1 bg-transparent border-none px-3 py-2 text-sm text-white focus:outline-none placeholder:text-slate-600"
                                        />
                                        <button
                                            onClick={() => handleComment(post.id)}
                                            className="p-2.5 bg-primary-600 text-white rounded-xl hover:bg-primary-500 transition-all shadow-lg shadow-primary-600/20"
                                        >
                                            <Send size={16} />
                                        </button>
                                    </div>
                                </div>
                            )}
                        </div>
                    ))}

                    {posts.length === 0 && (
                        <div className="text-center p-20 glass-card bg-slate-900/40 border-dashed border-slate-800">
                            <Plus size={48} className="mx-auto text-slate-700 mb-4 opacity-20" />
                            <p className="text-slate-500 font-medium">Your community feed is waiting for its first post.</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Sidebar Widgets */}
            <div className="space-y-6 lg:sticky lg:top-24">
                <div className="glass-card p-6 bg-slate-900 border-slate-800 border-t-4 border-t-primary-600 shadow-xl">
                    <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-2">
                            <Bell size={18} className="text-primary-500" />
                            <h3 className="text-base font-bold text-white">Notice Board</h3>
                        </div>
                        <span className="text-[10px] bg-slate-800 text-slate-400 px-2 py-1 rounded-lg font-bold">LIVE</span>
                    </div>
                    <div className="space-y-4">
                        {notices.map((notice, idx) => (
                            <div key={idx} className="p-4 bg-slate-800/40 rounded-2xl border border-slate-700/30 hover:bg-primary-500/5 hover:border-primary-500/30 transition-all cursor-pointer group">
                                <div className="flex items-center gap-2 mb-2">
                                    <div className="w-2 h-2 rounded-full bg-primary-500 shadow-sm shadow-primary-500/50"></div>
                                    <p className="text-[10px] text-primary-500 font-black uppercase tracking-tighter">Campus Update</p>
                                </div>
                                <h4 className="text-sm font-bold text-white group-hover:text-primary-400 transition-colors mb-1">{notice.title}</h4>
                                <p className="text-[11px] text-slate-500 line-clamp-2 leading-relaxed">{notice.description}</p>
                            </div>
                        ))}
                        <button className="w-full py-3 text-[11px] font-bold text-slate-500 hover:text-primary-500 transition-colors bg-slate-800/20 rounded-xl hover:bg-primary-500/5">
                            View All Announcements
                        </button>
                    </div>
                </div>

                <div className="glass-card p-6 bg-gradient-to-br from-primary-900/30 to-slate-900 border-primary-500/20 overflow-hidden relative group">
                    <div className="absolute -right-8 -bottom-8 text-primary-500/5 rotate-12 group-hover:rotate-0 transition-transform duration-700"><Heart size={160} /></div>
                    <div className="relative z-10">
                        <div className="flex items-center gap-2 mb-4">
                            <ShieldCheck size={16} className="text-emerald-500" />
                            <h3 className="text-emerald-500 font-black text-[10px] uppercase tracking-widest">Community Safety</h3>
                        </div>
                        <p className="text-3xl font-black text-white mb-1">98.4%</p>
                        <p className="text-xs text-slate-400 font-medium">AI-Moderated Integrity Score</p>
                        <div className="mt-6 w-full h-1.5 bg-white/5 rounded-full overflow-hidden">
                            <div className="h-full bg-emerald-500 w-[98.4%] shadow-sm shadow-emerald-500/50" />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

import React, { useState, useEffect, useRef } from 'react'
import { useAuth } from '../context/AuthContext'
import { supabase } from '../lib/supabase'
import { Search, Send, Hash, User, ShieldAlert, ArrowLeft, MessageSquare, Loader2, Plus, Trash2, X } from 'lucide-react'
import { moderateContent } from '../utils/moderation'
import { clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

function cn(...inputs) {
    return twMerge(clsx(inputs))
}

// Departments will be fetched from database

export default function Forums() {
    const { user, profile, isAdmin } = useAuth()
    const [departments, setDepartments] = useState([])
    const [activeForum, setActiveForum] = useState(null)
    const [search, setSearch] = useState('')
    const [showAdminModal, setShowAdminModal] = useState(false)
    const [newDeptName, setNewDeptName] = useState('')
    const [newDeptTheme, setNewDeptTheme] = useState('blue')

    // Chat state
    const [messages, setMessages] = useState([])
    const [newMessage, setNewMessage] = useState('')
    const [loading, setLoading] = useState(false)
    const [fetchingMessages, setFetchingMessages] = useState(false)
    const scrollRef = useRef()

    useEffect(() => {
        fetchDepartments()
    }, [])

    const fetchDepartments = async () => {
        const { data } = await supabase.from('forum_departments').select('*').order('name')
        if (data) setDepartments(data)
    }

    useEffect(() => {
        if (!activeForum) return

        fetchMessages()
        const channel = supabase
            .channel(`forum-${activeForum.id}`)
            .on(
                'postgres_changes',
                { event: 'INSERT', schema: 'public', table: 'messages', filter: `room_id=eq.forum-${activeForum.id}` },
                () => fetchMessages()
            )
            .subscribe()

        return () => { supabase.removeChannel(channel) }
    }, [activeForum])

    useEffect(() => {
        scrollRef.current?.scrollIntoView({ behavior: 'smooth' })
    }, [messages])

    const fetchMessages = async () => {
        setFetchingMessages(true)
        const { data } = await supabase
            .from('messages')
            .select('*, profiles(full_name, avatar_url)')
            .eq('room_id', `forum-${activeForum.id}`)
            .eq('status', 'approved')
            .order('created_at', { ascending: true })

        if (data) setMessages(data)
        setFetchingMessages(false)
    }

    const handleSend = async (e) => {
        e.preventDefault()
        if (!newMessage.trim() || loading) return

        setLoading(true)
        const content = newMessage
        setNewMessage('')

        try {
            const moderation = await moderateContent(content, 'message', user.id)
            if (moderation.flagged) {
                alert('≡ƒÜ½ Message blocked by AI ΓÇö contains inappropriate content.')
                setLoading(false)
                return
            }
            await supabase.from('messages').insert({
                sender_id: user.id,
                content: content,
                room_id: `forum-${activeForum.id}`,
                status: 'approved'
            })
        } catch (error) {
            alert('Failed to send message')
        } finally {
            setLoading(false)
        }
    }

    const handleAddDept = async (e) => {
        e.preventDefault()
        const { error } = await supabase.from('forum_departments').insert({ name: newDeptName, color_theme: newDeptTheme })
        if (error) alert(error.message)
        else {
            setShowAdminModal(false)
            setNewDeptName('')
            fetchDepartments()
        }
    }

    const handleDeleteDept = async (id, e) => {
        e.stopPropagation()
        if (!window.confirm('Delete this department forum?')) return
        const { error } = await supabase.from('forum_departments').delete().eq('id', id)
        if (error) alert(error.message)
        else fetchDepartments()
    }

    const canAccess = (dept) => {
        if (isAdmin) return true
        if (profile?.role === 'alumni') return profile?.department === dept.name
        return profile?.department === dept.name
    }

    const getThemeColors = (theme) => {
        const themes = {
            blue: { color: 'from-blue-500/20 to-indigo-500/20', text: 'text-blue-400' },
            emerald: { color: 'from-emerald-500/20 to-teal-500/20', text: 'text-emerald-400' },
            orange: { color: 'from-orange-500/20 to-red-500/20', text: 'text-orange-400' },
            purple: { color: 'from-purple-500/20 to-fuchsia-500/20', text: 'text-purple-400' },
            pink: { color: 'from-pink-500/20 to-rose-500/20', text: 'text-pink-400' },
        }
        return themes[theme] || themes.blue
    }

    const filteredDepts = departments.filter(d => d.name.toLowerCase().includes(search.toLowerCase()))

    // FORUM LIST VIEW
    if (!activeForum) {
        return (
            <div className="space-y-10 max-w-7xl mx-auto">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
                    <div>
                        <h2 className="text-3xl lg:text-4xl font-extrabold text-[var(--foreground)] tracking-tight">Departmental Forums</h2>
                        <p className="text-[var(--text-muted)] mt-1 font-medium italic">Join discussions specific to your field of study</p>
                    </div>
                </div>

                <div className="relative group animate-fade-in">
                    <Search size={22} className="absolute left-5 top-1/2 -translate-y-1/2 text-[var(--text-muted)] group-focus-within:text-primary-500 transition-colors" />
                    <input
                        type="text"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        placeholder="Search by department name..."
                        className="input-style w-full pl-14 pr-6 py-4.5 text-lg shadow-sm"
                    />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 lg:gap-8">
                    {filteredDepts.map(dept => {
                        const theme = getThemeColors(dept.color_theme)
                        const allowed = canAccess(dept)
                        return (
                            <div
                                key={dept.id}
                                onClick={() => allowed ? setActiveForum(dept) : alert(`Access Denied. You must be in the ${dept.name} department to join this forum.`)}
                                className={cn(
                                    "glass-card bg-[var(--card-bg)] border-[var(--card-border)] hover:border-primary-500 transition-all cursor-pointer p-8 group relative overflow-hidden flex flex-col min-h-[220px]",
                                    !allowed && "opacity-50 saturate-0 hover:opacity-100 hover:saturate-100"
                                )}
                            >
                                <div className="absolute top-0 right-0 p-10 opacity-[0.03] group-hover:scale-110 transition-transform">
                                    <Hash size={120} />
                                </div>

                                <div className="flex justify-between items-start mb-6 z-10">
                                    <div className={cn("w-14 h-14 rounded-2xl bg-slate-900/50 flex items-center justify-center border border-slate-700/50 shadow-xl", theme.text)}>
                                        <MessageSquare size={28} />
                                    </div>
                                    {isAdmin && (
                                        <button onClick={(e) => handleDeleteDept(dept.id, e)} className="p-2.5 text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all border border-rose-500/10 hover:border-rose-500/30">
                                            <Trash2 size={18} />
                                        </button>
                                    )}
                                </div>

                                <div className="z-10 flex-1">
                                    <h3 className="text-2xl font-black text-[var(--foreground)] group-hover:text-primary-600 transition-colors tracking-tight">{dept.name}</h3>
                                    <p className="text-[var(--text-muted)] text-sm mt-3 font-medium leading-relaxed">
                                        {allowed ? 'Community discussion and departmental updates.' : `Exclusive to identified ${dept.name} members.`}
                                    </p>
                                </div>

                                <div className="mt-6 flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-primary-500 z-10">
                                    {allowed ? <span>Join Interaction Room</span> : <span className="text-rose-500 flex items-center gap-1"><ShieldAlert size={12} /> Restricted Access</span>}
                                </div>
                            </div>
                        )
                    })}
                    {isAdmin && (
                        <div
                            onClick={() => setShowAdminModal(true)}
                            className="glass-card border-2 border-dashed border-[var(--card-border)] hover:border-primary-500 transition-all cursor-pointer p-8 flex flex-col items-center justify-center gap-4 text-[var(--text-muted)] hover:text-primary-500 group min-h-[220px]"
                        >
                            <div className="w-16 h-16 rounded-full bg-primary-500/10 flex items-center justify-center group-hover:scale-110 transition-transform">
                                <Plus size={32} />
                            </div>
                            <span className="font-black uppercase tracking-widest text-sm">Deploy New Forum</span>
                        </div>
                    )}
                </div>

                {showAdminModal && (
                    <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[100] flex items-center justify-center p-4 lg:p-6 animate-fade-in">
                        <div className="glass-card bg-[var(--card-bg)] border-[var(--card-border)] w-full max-w-md p-8 lg:p-10 shadow-2xl">
                            <div className="flex justify-between items-center mb-8">
                                <div>
                                    <h3 className="text-2xl font-black text-[var(--foreground)] tracking-tight">New Forum</h3>
                                    <p className="text-[var(--text-muted)] text-sm font-medium mt-1">Configure a new workspace</p>
                                </div>
                                <button onClick={() => setShowAdminModal(false)} className="p-2 text-[var(--text-muted)] hover:text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all">
                                    <X size={24} />
                                </button>
                            </div>

                            <form onSubmit={handleAddDept} className="space-y-6">
                                <div className="space-y-2">
                                    <label className="text-[11px] font-black text-primary-600 uppercase tracking-widest pl-1">Department Identifier</label>
                                    <input required value={newDeptName} onChange={e => setNewDeptName(e.target.value)} className="input-style w-full px-5 py-4" placeholder="e.g. Computer Science" />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[11px] font-black text-primary-600 uppercase tracking-widest pl-1">Aesthetic Sync</label>
                                    <select value={newDeptTheme} onChange={e => setNewDeptTheme(e.target.value)} className="input-style w-full px-5 py-4 appearance-none">
                                        <option value="blue">Sapphire Blue</option>
                                        <option value="emerald">Emerald Green</option>
                                        <option value="orange">Solar Orange</option>
                                        <option value="purple">Vibrant Purple</option>
                                        <option value="pink">Ruby Pink</option>
                                    </select>
                                </div>
                                <div className="flex gap-4 pt-4">
                                    <button type="button" onClick={() => setShowAdminModal(false)} className="flex-1 bg-[var(--input-bg)] hover:bg-slate-800 text-[var(--foreground)] font-bold py-4 rounded-2xl border border-[var(--card-border)] transition-all">Discard</button>
                                    <button type="submit" className="flex-2 bg-primary-600 hover:bg-primary-500 text-white font-black py-4 rounded-2xl shadow-xl shadow-primary-600/30 transition-all">Deploy Forum</button>
                                </div>
                            </form>
                        </div>
                    </div>
                )}
            </div>
        )
    }

    // CHAT VIEW
    return (
        <div className="flex flex-col h-[calc(100vh-6rem)] md:h-[calc(100vh-8rem)] max-w-7xl mx-auto glass-card bg-[var(--card-bg)] border-[var(--card-border)] overflow-hidden shadow-2xl animate-fade-in-up">
            {/* Header */}
            <div className="p-4 lg:p-6 border-b border-[var(--card-border)] flex items-center justify-between bg-[var(--card-bg)] z-10 shadow-sm relative overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-r from-primary-600/5 to-transparent pointer-events-none" />
                <div className="flex items-center gap-5 relative z-10">
                    <button
                        onClick={() => setActiveForum(null)}
                        className="w-12 h-12 rounded-[1.25rem] bg-[var(--input-bg)] border border-[var(--card-border)] flex items-center justify-center text-[var(--text-muted)] hover:text-primary-600 hover:bg-primary-500/10 transition-all hover:scale-110 active:scale-95 shadow-sm"
                        title="Exit Forum"
                    >
                        <ArrowLeft size={24} className="stroke-[2.5]" />
                    </button>
                    <div>
                        <div className="flex items-center gap-2">
                            <span className={cn("text-xs font-black uppercase tracking-[0.2em]", getThemeColors(activeForum.color_theme).text)}>
                                Departmental Live Forum
                            </span>
                        </div>
                        <h2 className="text-2xl font-black text-[var(--foreground)] flex items-center gap-2 tracking-tight">
                            <Hash size={24} className="text-primary-500" />
                            {activeForum.name}
                        </h2>
                    </div>
                </div>
                <div className="hidden sm:flex items-center gap-3 text-[10px] text-emerald-500 bg-emerald-500/5 px-4 py-2 rounded-2xl font-black uppercase tracking-[0.2em] border border-emerald-500/10 relative z-10">
                    <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)] animate-pulse" />
                    Secure Active Moderation
                </div>
            </div>

            {/* Messages */}
            <div className="flex-1 overflow-y-auto p-6 md:p-8 lg:p-10 space-y-10 scroll-smooth bg-[radial-gradient(circle_at_20%_20%,rgba(0,0,0,0.01),transparent)] flex flex-col">
                {fetchingMessages ? (
                    <div className="flex flex-col items-center justify-center h-full gap-4 text-[var(--text-muted)]">
                        <Loader2 className="animate-spin text-primary-500" size={48} />
                        <p className="text-xs font-black uppercase tracking-widest">Fetching Interactions...</p>
                    </div>
                ) : (
                    <>
                        <div className="flex-1 flex flex-col justify-end space-y-10">
                            {messages.map((msg) => (
                                <div key={msg.id} className={cn(
                                    "flex gap-4 group animate-fade-in-up",
                                    msg.sender_id === user.id ? 'flex-row-reverse' : ''
                                )}>
                                    <div className="w-12 h-12 rounded-2xl bg-[var(--input-bg)] border border-[var(--card-border)] flex-shrink-0 flex items-center justify-center text-[var(--text-muted)] group-hover:border-primary-500/30 transition-all shadow-sm self-end overflow-hidden">
                                        {msg.profiles?.avatar_url ? <img src={msg.profiles.avatar_url} alt="" className="w-full h-full object-cover transition-transform group-hover:scale-110" /> : <div className="font-black text-xs">{msg.profiles?.full_name?.charAt(0) || <User size={24} />}</div>}
                                    </div>
                                    <div className={cn(
                                        "max-w-[85%] sm:max-w-[70%] space-y-1.5",
                                        msg.sender_id === user.id ? 'text-right' : ''
                                    )}>
                                        <div className={cn(
                                            "flex gap-3 text-[10px] font-black uppercase tracking-widest text-[var(--text-muted)] mb-1",
                                            msg.sender_id === user.id ? 'flex-row-reverse px-2' : 'px-2'
                                        )}>
                                            <span>{msg.profiles?.full_name || 'Anonymous User'}</span>
                                            <span className="opacity-40 italic font-medium">{new Date(msg.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                        </div>
                                        <div className={cn(
