                                                ? 'bg-primary-600 text-white rounded-tr-none shadow-primary-600/10'
                                                : 'bg-[var(--input-bg)] text-[var(--foreground)] rounded-tl-none border border-[var(--card-border)]'
                                        )}>
                                            {msg.content}
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                        {messages.length === 0 && (
                            <div className="text-center py-24 px-10">
                                <div className="w-24 h-24 bg-[var(--input-bg)] rounded-[2.5rem] flex items-center justify-center mx-auto mb-6 text-primary-500 border border-[var(--card-border)]">
                                    <MessageSquare size={40} className="opacity-40" />
                                </div>
                                <h4 className="text-xl font-black text-[var(--foreground)] tracking-tight">Departmental Dialogue</h4>
                                <p className="text-sm text-[var(--text-muted)] max-w-sm mx-auto mt-2 italic font-medium">Welcome to the {activeForum.name} community. Be the first to start a conversation below.</p>
                            </div>
                        )}
                        <div ref={scrollRef} className="pt-2" />
                    </>
                )}
            </div>

            {/* Input Overlay */}
            <div className="p-6 md:p-8 lg:p-10 border-t border-[var(--card-border)] bg-[var(--card-bg)] shadow-[0_-10px_30px_rgba(0,0,0,0.1)] z-10">
                <form onSubmit={handleSend} className="relative group">
                    <div className="absolute inset-x-0 -top-px h-px bg-gradient-to-r from-transparent via-primary-500/20 to-transparent" />
                    <input
                        type="text"
                        value={newMessage}
                        onChange={(e) => setNewMessage(e.target.value)}
                        placeholder={`Broadcast a thought to #${activeForum.name}...`}
                        className="w-full bg-[var(--input-bg)] border-[var(--input-border)] rounded-[2rem] px-8 py-5 pr-20 text-[var(--foreground)] font-medium focus:outline-none focus:ring-4 focus:ring-primary-500/10 focus:border-primary-500 transition-all border shadow-inner text-lg"
                    />
                    <button
                        type="submit"
                        disabled={loading || !newMessage.trim()}
                        className="absolute right-2.5 top-2.5 bottom-2.5 bg-primary-600 hover:bg-primary-500 text-white w-14 rounded-[1.5rem] flex items-center justify-center transition-all disabled:opacity-50 shadow-lg shadow-primary-600/20 hover:scale-105 active:scale-95 group/send"
                    >
                        <Send size={22} className="group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-transform" />
                    </button>
                </form>
                <div className="flex items-center justify-between mt-5 px-2">
                    <p className="text-[10px] text-[var(--text-muted)] font-black uppercase tracking-[0.2em] flex items-center gap-2 opacity-60">
                        <ShieldAlert size={14} className="text-rose-500" />
                        <span>Identity Protected & AI Scanned</span>
                    </p>
                    <div className="flex gap-2">
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500/40" />
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500/20" />
                    </div>
                </div>
            </div>
        </div>
    )
}

import React, { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'
import { LogIn, UserPlus, Shield, Loader2, CheckCircle } from 'lucide-react'

export default function Login() {
    const [isLogin, setIsLogin] = useState(true)
    const [email, setEmail] = useState('')
    const [password, setPassword] = useState('')
    const [fullName, setFullName] = useState('')
    const [role, setRole] = useState('student')
    const [loading, setLoading] = useState(false)
    const [error, setError] = useState(null)
    const [success, setSuccess] = useState(null)

    const { signIn, signUp } = useAuth()
    const navigate = useNavigate()

    const handleSubmit = async (e) => {
        e.preventDefault()
        setLoading(true)
        setError(null)
        setSuccess(null)

        try {
            const isAdminEmail = email.toLowerCase() === 'prasanthanandarajan@gmail.com'
            const isCollegeEmail = email.toLowerCase().endsWith('@hicas.ac.in')

            if (isLogin) {
                if (!isAdminEmail && !isCollegeEmail) {
                    throw new Error('Access Denied: Please use your @hicas.ac.in college email to login.')
                }
                const { data, error } = await signIn({ email, password })
                if (error) {
                    if (error.message === 'Invalid login credentials') {
                        throw new Error('Wrong email or password. If you just signed up, make sure you confirmed your email or wait a moment and try again.')
                    }
                    if (error.message?.includes('Email not confirmed')) {
                        throw new Error('Please confirm your email first. Check your inbox for the confirmation link.')
                    }
                    throw error
                }
                if (data?.session) {
                    navigate('/')
                }
            } else {
                if (!isCollegeEmail) {
                    throw new Error('Sign-up Restricted: Only @hicas.ac.in college emails are allowed to create accounts.')
                }

                if (password.length < 6) {
                    throw new Error('Password must be at least 6 characters.')
                }

                const { data, error } = await signUp({
                    email,
                    password,
                    options: {
                        data: { full_name: fullName, role: role },
                        emailRedirectTo: window.location.origin
                    }
                })

                if (error) {
                    if (error.message?.includes('already registered') || error.message?.includes('already been registered')) {
                        throw new Error('This email is already registered. Try logging in instead!')
                    }
                    if (error.message?.includes('rate limit')) {
                        throw new Error('Too many attempts. Please wait 1-2 minutes and try again.')
                    }
                    if (error.message?.includes('valid email')) {
                        throw new Error('Please use a valid email address (e.g. yourname@gmail.com)')
                    }
                    throw new Error(error.message || 'Signup failed. Please try again.')
                }

                // If session exists, user is auto-confirmed -> go to app
                if (data?.session) {
                    navigate('/')
                    return
                }

                // If user exists but no session, email confirmation is needed
                if (data?.user) {
                    setSuccess('Γ£à Account created! Check your email for a confirmation link, then come back and log in.')
                    setIsLogin(true)
                    setPassword('')
                } else {
                    // Fallback
                    setSuccess('Γ£à Account created! Switch to Login and sign in.')
                    setIsLogin(true)
                }
            }
        } catch (err) {
            setError(err.message || 'Something went wrong. Please try again.')
        } finally {
            setLoading(false)
        }
    }

    return (
        <div className="min-h-screen bg-[var(--background)] flex items-center justify-center p-4 lg:p-12 relative overflow-hidden">
            {/* Animated Background Elements */}
            <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-primary-600/10 rounded-full blur-[120px] animate-pulse"></div>
            <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-600/10 rounded-full blur-[120px] animate-pulse transition-all duration-500 delay-700"></div>

            <div className="w-full max-w-[440px] relative z-10 animate-fade-in">
                <div className="text-center mb-10">
                    <div className="inline-flex w-20 h-20 bg-primary-600 rounded-3xl items-center justify-center text-white mb-6 transform rotate-12 shadow-2xl shadow-primary-600/30 ring-4 ring-white/5">
                        <Shield size={40} className="drop-shadow-lg" />
                    </div>
                    <h2 className="text-4xl font-extrabold text-[var(--foreground)] tracking-tight">CollegeCommunity</h2>
                    <p className="text-[var(--text-muted)] mt-2 font-medium">Connecting Minds, Moderated by AI</p>
                </div>

                <div className="glass-card p-6 lg:p-10 shadow-2xl bg-[var(--card-bg)] border-[var(--card-border)]">
                    <div className="flex p-1.5 bg-[var(--input-bg)] border border-[var(--input-border)] rounded-2xl mb-8">
                        <button
                            onClick={() => { setIsLogin(true); setError(null); setSuccess(null) }}
                            className={cn(
                                "flex-1 py-3 rounded-[14px] text-sm font-bold transition-all duration-300",
                                isLogin
                                    ? "bg-primary-600 text-white shadow-xl shadow-primary-600/20"
                                    : "text-[var(--text-muted)] hover:text-[var(--foreground)]"
                            )}
                        >
                            Login
                        </button>
                        <button
                            onClick={() => { setIsLogin(false); setError(null); setSuccess(null) }}
                            className={cn(
                                "flex-1 py-3 rounded-[14px] text-sm font-bold transition-all duration-300",
                                !isLogin
                                    ? "bg-primary-600 text-white shadow-xl shadow-primary-600/20"
                                    : "text-[var(--text-muted)] hover:text-[var(--foreground)]"
                            )}
                        >
                            Sign Up
                        </button>
                    </div>

                    <form onSubmit={handleSubmit} className="space-y-4">
                        {!isLogin && (
                            <div className="space-y-4">
                                <div>
                                    <label className="text-[11px] font-black text-primary-600 mb-1.5 block uppercase tracking-widest pl-1">Full Name</label>
                                    <input
                                        type="text"
                                        value={fullName}
                                        onChange={(e) => setFullName(e.target.value)}
                                        className="input-style w-full px-5 py-3.5"
                                        placeholder="John Doe"
                                        required
                                    />
                                </div>
                                <div>
                                    <label className="text-[11px] font-black text-primary-600 mb-1.5 block uppercase tracking-widest pl-1">I am a...</label>
                                    <div className="relative">
                                        <select
                                            value={role}
                                            onChange={(e) => setRole(e.target.value)}
                                            className="input-style w-full px-5 py-3.5 appearance-none cursor-pointer"
                                        >
                                            <option value="student">Student</option>
                                            <option value="faculty">Faculty Member</option>
                                            <option value="alumni">Alumni / Mentor</option>
                                        </select>
                                        <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400">
                                            <Shield size={16} />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        )}
                        <div>
                            <label className="text-[11px] font-black text-primary-600 mb-1.5 block uppercase tracking-widest pl-1">Email Address</label>
                            <input
                                type="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                className="input-style w-full px-5 py-3.5"
                                placeholder="you@hicas.ac.in"
                                required
                            />
                        </div>
                        <div>
                            <label className="text-[11px] font-black text-primary-600 mb-1.5 block uppercase tracking-widest pl-1">Password</label>
                            <input
                                type="password"
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="input-style w-full px-5 py-3.5"
                                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                                required
                                minLength={6}
                            />
                        </div>

                        {error && (
                            <p className="text-rose-500 text-xs mt-2 bg-rose-500/10 p-3 rounded-lg border border-rose-500/20">
                                ΓÜá∩╕Å {error}
                            </p>
                        )}

                        {success && (
                            <div className="text-emerald-500 text-xs mt-2 bg-emerald-500/10 p-3 rounded-lg border border-emerald-500/20 flex items-start gap-2">
                                <CheckCircle size={16} className="flex-shrink-0 mt-0.5" />
                                <span>{success}</span>
                            </div>
                        )}

                        <button
                            type="submit"
                            disabled={loading}
                            className="w-full bg-primary-600 hover:bg-primary-500 text-white font-black py-4 rounded-2xl mt-6 shadow-2xl shadow-primary-600/30 flex items-center justify-center gap-3 transition-all active:scale-[0.98] disabled:opacity-50"
                        >
                            {loading ? (
                                <><Loader2 size={22} className="animate-spin" /> Processing...</>
                            ) : (
                                isLogin ? <><LogIn size={22} /> Access Feed</> : <><UserPlus size={22} /> Create Account</>
                            )}
                        </button>
                    </form>
                </div>
            </div>
        </div>
    )
}

function cn(...inputs) {
    return inputs.filter(Boolean).join(' ')
}

import React, { useState, useEffect } from 'react'
import { useAuth } from '../context/AuthContext'
import { supabase } from '../lib/supabase'
import { Search, MapPin, Plus, Loader2, AlertCircle, CheckCircle, PackageSearch, X, Filter } from 'lucide-react'
import { clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'
import { moderateContent } from '../utils/moderation'

function cn(...inputs) {
    return twMerge(clsx(inputs))
}

export default function LostFound() {
    const { user } = useAuth()
    const [items, setItems] = useState([])
    const [loading, setLoading] = useState(true)
    const [filter, setFilter] = useState('all') // 'all', 'lost', 'found'
    const [showModal, setShowModal] = useState(false)

    // Form state
    const [title, setTitle] = useState('')
    const [description, setDescription] = useState('')
    const [location, setLocation] = useState('')
    const [itemType, setItemType] = useState('lost') // 'lost' or 'found'
    const [contactInfo, setContactInfo] = useState('')

    useEffect(() => {
        fetchItems()
        const channel = supabase
            .channel('lostfound-realtime')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'lost_found' }, () => {
                fetchItems()
            })
            .subscribe()
        return () => { supabase.removeChannel(channel) }
    }, [])

    const fetchItems = async () => {
        const { data, error } = await supabase
            .from('lost_found')
            .select('*, profiles(full_name)')
            .order('created_at', { ascending: false })

        if (error) console.error(error)
        else setItems(data)
        setLoading(false)
    }

    const handleCreate = async (e) => {
        e.preventDefault()
        setLoading(true)

        try {
            // Moderate content
            const contentToModerate = `${title} ${description}`
            const result = await moderateContent(contentToModerate, 'lost_found', user.id)
            if (result.flagged) {
                alert('≡ƒÜ½ Item report blocked by AI. Contains inappropriate content.')
                setLoading(false)
                return
            }

            const { error } = await supabase.from('lost_found').insert({
                reporter_id: user.id,
                title,
                description,
                location,
                item_type: itemType,
                contact_info: contactInfo
            })

            if (error) throw error

            setShowModal(false)
            setTitle(''); setDescription(''); setLocation(''); setContactInfo('')
        } catch (err) {
            alert(err.message)
        } finally {
            setLoading(false)
        }
    }

    const handleResolve = async (id) => {
        const { error } = await supabase
            .from('lost_found')
            .update({ resolved: true })
            .eq('id', id)
        if (error) alert('Failed to mark as resolved: ' + error.message)
        else fetchItems()
    }

    const filteredItems = items.filter(item => {
        if (filter === 'all') return true
        return item.item_type === filter
    })

    return (
        <div className="space-y-10 max-w-7xl mx-auto">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <div>
                    <h2 className="text-3xl lg:text-4xl font-black text-[var(--foreground)] tracking-tight">Lost & Found Hub</h2>
                    <p className="text-[var(--text-muted)] mt-1 font-medium italic">Recover your belongings or help others find theirs</p>
                </div>
                <button
                    onClick={() => setShowModal(true)}
                    className="flex items-center justify-center gap-2 bg-primary-600 hover:bg-primary-500 text-white px-8 py-4 rounded-[1.5rem] font-black text-xs uppercase tracking-widest shadow-xl shadow-primary-600/20 transition-all hover:scale-105 active:scale-95 group w-full md:w-auto"
                >
                    <Plus size={18} className="group-hover:rotate-90 transition-transform duration-300" />
                    <span>Report Item</span>
                </button>
            </div>

            {/* Interaction Bar */}
            <div className="flex flex-col sm:flex-row gap-4 items-center bg-[var(--input-bg)] p-3 rounded-[2rem] border border-[var(--card-border)] shadow-inner animate-fade-in">
                <div className="flex gap-2 w-full sm:w-auto">
                    {['all', 'lost', 'found'].map(t => (
                        <button
                            key={t}
                            onClick={() => setFilter(t)}
                            className={cn(
                                "flex-1 sm:flex-none px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all",
                                filter === t
                                    ? "bg-[var(--foreground)] text-[var(--card-bg)] shadow-lg"
                                    : "text-[var(--text-muted)] hover:text-[var(--foreground)]"
                            )}
                        >
                            {t}
                        </button>
                    ))}
                </div>
                <div className="h-4 w-px bg-[var(--card-border)] hidden sm:block mx-2" />
                <div className="flex items-center gap-2 text-[var(--text-muted)] px-4">
                    <Filter size={14} />
                    <span className="text-[10px] font-black uppercase tracking-widest">Display Filter</span>
                </div>
            </div>

            {loading ? (
                <div className="flex flex-col items-center justify-center py-32 gap-4 text-[var(--text-muted)]">
                    <Loader2 className="text-primary-500 animate-spin" size={48} />
                    <p className="font-black text-[10px] uppercase tracking-widest">Scanning Campus Records...</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 lg:gap-10 animate-fade-in-up">
                    {filteredItems.map(item => (
                        <div key={item.id} className={cn(
                            "glass-card bg-[var(--card-bg)] border-[var(--card-border)] overflow-hidden transition-all duration-500 group hover:border-primary-500/50 hover:shadow-2xl flex flex-col h-full",
                            item.resolved ? 'opacity-40 grayscale-[0.5]' : ''
                        )}>
                            <div className={cn(
                                "p-4 border-b flex justify-between items-center transition-colors",
                                item.item_type === 'lost'
                                    ? 'border-rose-500/20 bg-rose-500/5 group-hover:bg-rose-500/10'
                                    : 'border-emerald-500/20 bg-emerald-500/5 group-hover:bg-emerald-500/10'
                            )}>
                                <div className={cn(
                                    "flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em]",
                                    item.item_type === 'lost' ? 'text-rose-500' : 'text-emerald-500'
                                )}>
                                    {item.item_type === 'lost' ? <AlertCircle size={14} className="stroke-[3]" /> : <CheckCircle size={14} className="stroke-[3]" />}
                                    <span>{item.item_type} Item</span>
                                </div>
                                {item.resolved && (
                                    <span className="text-[9px] bg-[var(--input-bg)] text-[var(--text-muted)] px-3 py-1 rounded-full font-black uppercase tracking-widest border border-[var(--card-border)]">
                                        Handled
                                    </span>
                                )}
                            </div>
                            <div className="p-8 flex-1 flex flex-col space-y-5">
                                <h3 className="text-2xl font-black text-[var(--foreground)] tracking-tight line-clamp-2 leading-tight">{item.title}</h3>
                                <p className="text-[var(--text-muted)] text-sm font-medium line-clamp-3 leading-relaxed">{item.description}</p>
                            </div>

                            <div className="px-8 pb-8 space-y-4">
                                <div className="space-y-3 pt-6 border-t border-[var(--card-border)]">
                                    <div className="flex items-center gap-3 text-xs font-bold text-[var(--text-muted)]">
                                        <div className="w-8 h-8 rounded-lg bg-[var(--input-bg)] flex items-center justify-center text-primary-500 shadow-sm">
                                            <MapPin size={16} />
                                        </div>
                                        <span>{item.location}</span>
                                    </div>
                                    <div className="flex items-center gap-3 text-xs font-bold text-[var(--text-muted)]">
                                        <div className="w-8 h-8 rounded-lg bg-[var(--input-bg)] flex items-center justify-center text-emerald-500 shadow-sm">
                                            <PackageSearch size={16} />
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[10px] uppercase tracking-widest opacity-40">Contact</span>
                                            <span>{item.contact_info || item.profiles?.full_name}</span>
                                        </div>
                                    </div>
                                </div>

                                {!item.resolved && item.reporter_id === user.id && (
                                    <button
                                        onClick={() => handleResolve(item.id)}
                                        className="w-full bg-emerald-500/10 hover:bg-emerald-500 text-emerald-600 hover:text-white text-[10px] font-black uppercase tracking-[0.2em] py-4 rounded-2xl transition-all border border-emerald-500/10"
                                    >
                                        Mark as Resolved
                                    </button>
                                )}
                            </div>
                        </div>
                    ))}

                    {filteredItems.length === 0 && (
                        <div className="col-span-full py-32 flex flex-col items-center justify-center glass-card bg-[var(--input-bg)] border-dashed border-[var(--card-border)] text-center px-10">
                            <div className="w-24 h-24 bg-[var(--card-bg)] rounded-[2.5rem] flex items-center justify-center text-[var(--text-muted)] opacity-20 mb-6 rotate-12">
                                <PackageSearch size={48} />
                            </div>
                            <h4 className="text-xl font-black text-[var(--foreground)] tracking-tight">Search Result Empty</h4>
                            <p className="text-sm text-[var(--text-muted)] max-w-xs mt-2 font-medium">No campus reports matching "{filter}" were found in our temporary vault.</p>
                        </div>
                    )}
                </div>
            )}

            {/* Create Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[100] flex items-center justify-center p-4 lg:p-6 animate-fade-in">
                    <div className="glass-card bg-[var(--card-bg)] border-[var(--card-border)] w-full max-w-xl p-8 lg:p-12 max-h-[90vh] overflow-y-auto shadow-2xl relative">
                        <div className="flex justify-between items-start mb-10">
                            <div>
                                <h3 className="text-3xl font-black text-[var(--foreground)] tracking-tight">Report Canvas Item</h3>
                                <p className="text-[var(--text-muted)] font-medium mt-1 italic">Providing details helps fast recovery</p>
                            </div>
                            <button onClick={() => setShowModal(false)} className="p-3 text-[var(--text-muted)] hover:text-rose-500 hover:bg-rose-500/10 rounded-2xl transition-all group">
                                <X size={24} className="group-hover:rotate-90 transition-transform" />
                            </button>
                        </div>

                        <form onSubmit={handleCreate} className="space-y-8">
                            <div className="flex gap-4 p-2 bg-[var(--input-bg)] rounded-[2rem] border border-[var(--card-border)] shadow-inner">
                                <button
                                    type="button"
                                    onClick={() => setItemType('lost')}
                                    className={cn(
                                        "flex-1 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest transition-all",
                                        itemType === 'lost' ? 'bg-rose-500 text-white shadow-xl shadow-rose-500/20' : 'text-[var(--text-muted)] hover:text-[var(--foreground)]'
                                    )}
                                >
                                    I Lost Something
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setItemType('found')}
                                    className={cn(
                                        "flex-1 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest transition-all",
                                        itemType === 'found' ? 'bg-emerald-500 text-white shadow-xl shadow-emerald-500/20' : 'text-[var(--text-muted)] hover:text-[var(--foreground)]'
                                    )}
                                >
                                    I Found Something
                                </button>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                <div className="space-y-2">
                                    <label className="text-[11px] font-black text-primary-600 uppercase tracking-widest pl-1">Item Title</label>
                                    <input
                                        required
                                        value={title}
                                        onChange={(e) => setTitle(e.target.value)}
                                        className="input-style w-full px-6 py-4"
                                        placeholder="e.g. Silver Laptop, Lab Journal"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[11px] font-black text-primary-600 uppercase tracking-widest pl-1">Location Coordinates</label>
                                    <input
                                        required
                                        value={location}
                                        onChange={(e) => setLocation(e.target.value)}
                                        className="input-style w-full px-6 py-4"
                                        placeholder="e.g. Block A, Room 402"
                                    />
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[11px] font-black text-primary-600 uppercase tracking-widest pl-1">Visual & Physical Trace</label>
                                <textarea
                                    required
                                    value={description}
                                    onChange={(e) => setDescription(e.target.value)}
                                    className="input-style w-full px-6 py-4 h-32 resize-none"
                                    placeholder="Mention brand, colors, identification stickers, etc."
                                />
                            </div>

                            <div className="space-y-2">
                                <label className="text-[11px] font-black text-primary-600 uppercase tracking-widest pl-1">Secure Contact Link (Optional)</label>
                                <input
                                    value={contactInfo}
                                    onChange={(e) => setContactInfo(e.target.value)}
                                    className="input-style w-full px-6 py-4"
                                    placeholder="WhatsApp, Phone, or Dorm detail"
                                />
                            </div>

                            <div className="flex gap-4 pt-6">
                                <button
                                    type="button"
                                    onClick={() => setShowModal(false)}
                                    className="flex-1 bg-[var(--input-bg)] hover:bg-slate-800 text-[var(--foreground)] font-black py-5 rounded-[2rem] transition-all border border-[var(--card-border)] uppercase text-[10px] tracking-widest"
                                >
                                    Discard
                                </button>
                                <button
                                    type="submit"
                                    disabled={loading}
                                    className="flex-2 bg-primary-600 hover:bg-primary-500 text-white font-black py-5 rounded-[2rem] shadow-2xl shadow-primary-600/30 transition-all uppercase text-[10px] tracking-[0.2em] flex items-center justify-center gap-3 active:scale-95 disabled:opacity-50"
                                >
                                    {loading ? <Loader2 className="animate-spin" size={18} /> : <span>Dispatch Report</span>}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    )
}

import React, { useState, useEffect, useRef } from 'react'
import { useAuth } from '../context/AuthContext'
import { supabase } from '../lib/supabase'
import { User, Mail, Shield, Edit3, Camera, Loader2, Save, X, GraduationCap, Award, MapPin, Calendar } from 'lucide-react'
import { moderateContent } from '../utils/moderation'
import { clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

function cn(...inputs) {
    return twMerge(clsx(inputs))
}

export default function Profile() {
    const { user, profile, refreshProfile } = useAuth()
    const [editing, setEditing] = useState(false)
    const [fullName, setFullName] = useState(profile?.full_name || '')
    const [department, setDepartment] = useState(profile?.department || '')
    const [loading, setLoading] = useState(false)
    const [avatarLoading, setAvatarLoading] = useState(false)
    const [avatarUrl, setAvatarUrl] = useState(profile?.avatar_url || null)
    const fileInputRef = useRef(null)


    useEffect(() => {
    }, [profile])


    const handleAvatarUpload = async (e) => {
        const file = e.target.files[0]
        if (!file) return
        if (file.size > 2 * 1024 * 1024) {
            alert('Image must be less than 2MB')
            return
        }

        setAvatarLoading(true)
        try {
            const fileExt = file.name.split('.').pop()
            const fileName = `${user.id}-${Date.now()}.${fileExt}`

            const { error: uploadError } = await supabase.storage
                .from('avatars')
                .upload(fileName, file)

            if (uploadError) throw uploadError

            const { data: { publicUrl } } = supabase.storage
                .from('avatars')
                .getPublicUrl(fileName)

            // Update profile with new avatar URL
            const { error: updateError } = await supabase
                .from('profiles')
                .update({ avatar_url: publicUrl })
                .eq('id', user.id)

            if (updateError) throw updateError

            setAvatarUrl(publicUrl)
            alert('Avatar updated! Refresh the page to see it everywhere.')
        } catch (err) {
            alert('Upload failed: ' + err.message)
        } finally {
            setAvatarLoading(false)
        }
    }

    const handleUpdate = async (e) => {
        e.preventDefault()

        // Email Domain Validation
        if (!user.email.endsWith('@hicas.ac.in')) {
            alert('≡ƒÜ½ Access Restricted: Only @hicas.ac.in email addresses can update profiles or use platform features.')
            return
        }

        setLoading(true)

        try {
            // Moderate full name
            const result = await moderateContent(fullName, 'profile', user.id)
            if (result.flagged) {
                alert('≡ƒÜ½ Profile update blocked by AI. Your name contains inappropriate content.')
                setLoading(false)
                return
            }

            const { error } = await supabase
                .from('profiles')
                .update({
                    full_name: fullName,
                    department: department
                })
                .eq('id', user.id)

            if (error) throw error


            setEditing(false)
            alert('Profile updated! Refresh the page to see changes.')
        } catch (err) {
            alert(err.message)
        } finally {
            setLoading(false)
        }
    }

    const handleRoleChange = async (newRole) => {
        if (!window.confirm(`Are you sure you want to change your role to ${newRole}?`)) return
        setLoading(true)
        try {
            const { error } = await supabase
                .from('profiles')
                .update({ role: newRole })
                .eq('id', user.id)
            if (error) throw error
            alert('Role updated! You are now an Alumni.')
            refreshProfile()
        } catch (err) {
            alert(err.message)
        } finally {
            setLoading(false)
        }
    }

    return (
        <div className="max-w-7xl mx-auto space-y-10">
            {/* Profile Hero Header */}
            <div className="glass-card bg-[var(--card-bg)] border-[var(--card-border)] p-0 overflow-hidden shadow-2xl animate-fade-in">
                {/* Banner Area */}
                <div className="h-48 bg-gradient-to-br from-primary-600/40 via-primary-900/40 to-[var(--card-bg)] relative">
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_20%_20%,rgba(255,255,255,0.1),transparent)]" />
                    <div className="absolute inset-0 bg-gradient-to-t from-[var(--card-bg)] to-transparent" />
                </div>

                <div className="px-8 pb-10 -mt-20">
                    <div className="flex flex-col md:flex-row items-end gap-8">
                        {/* Avatar Section */}
                        <div className="relative group shrink-0">
                            <div className="w-40 h-40 rounded-[2.5rem] bg-[var(--input-bg)] border-8 border-[var(--card-bg)] overflow-hidden shadow-2xl flex items-center justify-center text-[var(--text-muted)] ring-1 ring-[var(--card-border)]">
                                {avatarUrl ? (
                                    <img src={avatarUrl} alt="Profile" className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                                ) : (
                                    <User size={80} className="opacity-20" />
                                )}
                                {avatarLoading && (
                                    <div className="absolute inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center">
                                        <Loader2 size={40} className="animate-spin text-primary-500" />
                                    </div>
                                )}
                            </div>
                            <input
                                type="file"
                                ref={fileInputRef}
                                onChange={handleAvatarUpload}
                                accept="image/*"
                                className="hidden"
                            />
                            <button
                                onClick={() => fileInputRef.current?.click()}
                                className="absolute bottom-4 right-4 p-3 bg-primary-600 text-white rounded-2xl shadow-xl ring-4 ring-[var(--card-bg)] hover:bg-primary-500 transition-all hover:scale-110 active:scale-95"
                                title="Change Avatar"
                            >
                                <Camera size={18} className="stroke-[2.5]" />
                            </button>
                        </div>

                        {/* Name & Bio Area */}
                        <div className="flex-1 pb-4 text-center md:text-left">
                            <div className="flex flex-col md:flex-row md:items-center gap-3">
                                <h2 className="text-4xl lg:text-5xl font-black text-[var(--foreground)] tracking-tighter drop-shadow-sm">{profile?.full_name}</h2>
                                <div className="flex items-center justify-center md:justify-start gap-2">
                                    <span className="bg-primary-500/10 text-primary-600 px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest border border-primary-500/10">
                                        Verified {profile?.role}
                                    </span>
                                </div>
                            </div>
                            <div className="flex flex-wrap justify-center md:justify-start gap-5 mt-4">
                                <div className="flex items-center gap-2 text-[var(--text-muted)] font-bold text-sm">
                                    <Mail size={16} className="text-primary-500" />
                                    <span>{user?.email}</span>
                                </div>
                                {profile?.department && (
                                    <div className="flex items-center gap-2 text-[var(--text-muted)] font-bold text-sm">
                                        <GraduationCap size={16} className="text-rose-500" />
                                        <span>{profile.department}</span>
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* Actions Area */}
                        <div className="flex flex-col sm:flex-row gap-3 pb-4 w-full md:w-auto">
                            {profile?.role === 'student' && (
                                <button
                                    onClick={() => handleRoleChange('alumni')}
                                    className="flex items-center justify-center gap-2 px-6 py-3.5 bg-emerald-500/10 hover:bg-emerald-500 text-emerald-600 hover:text-white rounded-2xl font-black text-xs transition-all border border-emerald-500/10 uppercase tracking-widest shadow-sm shadow-emerald-500/5 group"
                                >
                                    <GraduationCap size={16} className="group-hover:rotate-12 transition-transform" />
                                    <span>Graduated</span>
                                </button>
                            )}
                            <button
                                onClick={() => setEditing(!editing)}
                                className={cn(
                                    "flex items-center justify-center gap-2 px-8 py-3.5 rounded-2xl font-black text-xs transition-all border uppercase tracking-widest shadow-sm",
                                    editing
                                        ? "bg-rose-500/10 text-rose-500 border-rose-500/10 hover:bg-rose-500 hover:text-white"
                                        : "bg-[var(--foreground)] text-[var(--card-bg)] border-[var(--foreground)] hover:opacity-90"
                                )}
                            >
                                {editing ? <><X size={16} /> <span>Cancel</span></> : <><Edit3 size={16} /> <span>Edit Profile</span></>}
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 lg:gap-10 animate-fade-in-up">
                <div className="lg:col-span-2 space-y-8">
                    {editing ? (
                        <div className="glass-card p-8 lg:p-12 bg-[var(--card-bg)] border-[var(--card-border)] shadow-xl relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-8 opacity-5">
                                <Edit3 size={120} />
                            </div>
                            <div className="relative">
                                <h3 className="text-3xl font-black text-[var(--foreground)] mb-2 tracking-tight">Edit Identity</h3>
                                <p className="text-[var(--text-muted)] font-medium mb-10">Keep your details updated for the community</p>

                                <form onSubmit={handleUpdate} className="space-y-8">
                                    <div className="space-y-3">
                                        <label className="text-[11px] font-black text-primary-600 uppercase tracking-[0.2em] pl-1">Full Name</label>
                                        <input
                                            type="text"
                                            value={fullName}
                                            onChange={(e) => setFullName(e.target.value)}
                                            className="input-style w-full px-6 py-4.5 text-lg"
                                            placeholder="Your Display Name"
                                        />
                                    </div>

                                    <div className="space-y-3">
                                        <label className="text-[11px] font-black text-primary-600 uppercase tracking-[0.2em] pl-1">Primary Department</label>
                                        <select
                                            value={department}
                                            onChange={(e) => setDepartment(e.target.value)}
                                            className="input-style w-full px-6 py-4.5 text-lg appearance-none bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIGZpbGw9Im5vbmUiIHZpZXdCb3g9IjAgMCAyNCAyNCIgc3Ryb2tlPSJjdXJyZW50Q29sb3IiIHN0cm9rZS13aWR0aD0iMiIgc3Ryb2tlLWxpbmVjYXA9InJvdW5kIiBzdHJva2UtbGluZWpvaW49InJvdW5kIj48cGF0aCBkPSJtNiA5IDYgNiA2LTYiLz48L3N2Zz4=')] bg-[length:1.5rem] bg-[right_1.5rem_center] bg-no-repeat"
                                        >
                                            <option value="">Select Department</option>
                                            <option value="Computer Science">Computer Science & IT</option>
                                            <option value="Information Tech">Information Technology</option>
                                            <option value="Mechanical Eng">Mechanical Engineering</option>
                                            <option value="Civil Eng">Civil Engineering</option>
                                            <option value="Electronics & Comm">Electronics & Communication</option>
                                            <option value="Electrical Eng">Electrical Engineering</option>
                                        </select>
                                        <p className="text-[10px] text-[var(--text-muted)] font-black uppercase tracking-wider mt-2 opacity-60">* This determines your access to specialized departmental forum feeds.</p>
                                    </div>

                                    <button
                                        disabled={loading}
                                        className="w-full bg-primary-600 hover:bg-primary-500 text-white font-black py-5 rounded-[2rem] mt-6 shadow-2xl shadow-primary-600/30 transition-all active:scale-[0.98] disabled:opacity-50 flex items-center justify-center gap-3 text-lg uppercase tracking-widest"
                                    >
                                        {loading ? <><Loader2 size={24} className="animate-spin" /> <span>Syncing...</span></> : <><Save size={24} /> <span>Save Profile</span></>}
                                    </button>
                                </form>
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-8">
                            {/* Stats Overview */}
                            <div className="glass-card p-10 bg-[var(--card-bg)] border-[var(--card-border)] shadow-xl">
                                <h3 className="text-2xl font-black text-[var(--foreground)] mb-8 tracking-tight flex items-center gap-3">
                                    <Award size={24} className="text-primary-500" />
                                    <span>Contribution Hub</span>
                                </h3>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                                    <div className="bg-gradient-to-br from-[var(--input-bg)] to-[var(--card-bg)] p-8 rounded-[2rem] border border-[var(--card-border)] shadow-inner group hover:border-primary-500/30 transition-colors">
                                        <p className="text-[var(--text-muted)] text-[10px] font-black uppercase tracking-[0.2em] mb-3">Total Activity</p>
                                        <div className="flex items-center justify-between">
                                            <p className="text-5xl font-black text-[var(--foreground)] group-hover:text-primary-600 transition-colors">12</p>
                                            <div className="w-14 h-14 rounded-2xl bg-primary-500/10 flex items-center justify-center text-primary-500">
                                                <Edit3 size={28} />
                                            </div>
                                        </div>
                                        <p className="text-xs font-bold text-[var(--text-muted)] mt-4">Posts shared with community</p>
                                    </div>
                                    <div className="bg-gradient-to-br from-[var(--input-bg)] to-[var(--card-bg)] p-8 rounded-[2rem] border border-[var(--card-border)] shadow-inner group hover:border-emerald-500/30 transition-colors">
                                        <p className="text-[var(--text-muted)] text-[10px] font-black uppercase tracking-[0.2em] mb-3">Global Impact</p>
                                        <div className="flex items-center justify-between">
                                            <p className="text-5xl font-black text-emerald-500">840</p>
                                            <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 flex items-center justify-center text-emerald-500">
                                                <Award size={28} />
                                            </div>
                                        </div>
                                        <p className="text-xs font-bold text-[var(--text-muted)] mt-4">Calculated from peer engagement</p>
                                    </div>
                                </div>
                            </div>

                            {/* Recent Activity Placeholder */}
                            <div className="glass-card p-8 bg-[var(--card-bg)] border-[var(--card-border)] border-dashed opacity-50 flex flex-col items-center justify-center text-center py-16">
                                <Calendar size={48} className="text-[var(--text-muted)] mb-4" />
                                <h4 className="text-lg font-black text-[var(--foreground)]">Activity Log Coming Soon</h4>
                                <p className="text-sm text-[var(--text-muted)] max-w-xs mt-2">We're building a detailed history of your interactions within the HICAS community.</p>
                            </div>
                        </div>
                    )}
                </div>

                <div className="space-y-8">
                    {/* Security Card */}
                    <div className="glass-card p-8 bg-[var(--card-bg)] border-[var(--card-border)] shadow-xl relative overflow-hidden group">
                        <div className="absolute -right-4 -top-4 opacity-5 group-hover:opacity-10 transition-opacity">
                            <Shield size={120} />
                        </div>
                        <h3 className="text-xl font-black text-[var(--foreground)] mb-6 tracking-tight uppercase tracking-widest text-sm">Vault Status</h3>
                        <div className="space-y-6">
                            <div className="flex items-center justify-between p-4 rounded-xl bg-[var(--input-bg)] border border-[var(--card-border)]">
                                <div className="flex items-center gap-3">
                                    <div className="w-2 h-2 rounded-full bg-rose-500 shadow-[0_0_8px_rgba(244,63,94,0.6)] animate-pulse" />
                                    <span className="text-xs font-bold text-[var(--text-muted)]">2FA Shield</span>
                                </div>
                                <span className="text-[10px] font-black text-rose-500 uppercase tracking-widest bg-rose-500/10 px-2 py-1 rounded">Inactive</span>
                            </div>
                            <div className="flex items-center justify-between p-4 rounded-xl bg-[var(--input-bg)] border border-[var(--card-border)]">
                                <div className="flex items-center gap-3">
                                    <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.6)]" />
                                    <span className="text-xs font-bold text-[var(--text-muted)]">Audit Logs</span>
                                </div>
                                <span className="text-[10px] font-black text-emerald-500 uppercase tracking-widest bg-emerald-500/10 px-2 py-1 rounded">Active</span>
                            </div>
                        </div>
                        <p className="text-[10px] text-[var(--text-muted)] mt-6 font-medium italic opacity-60">Security features are managed by the HICAS Central Admin panel.</p>
                    </div>

                    {/* Quick Links Card */}
                    <div className="glass-card p-8 bg-primary-600 text-white shadow-2xl shadow-primary-600/20 relative overflow-hidden group hover:scale-[1.02] transition-transform">
                        <div className="absolute -left-4 -bottom-4 opacity-10">
                            <GraduationCap size={140} />
                        </div>
                        <h3 className="text-xl font-black mb-4 relative z-10">Network Hub</h3>
                        <p className="text-primary-100 text-sm font-medium mb-6 relative z-10 leading-relaxed">Join departmental forums or participate in upcoming events to boost your impact score.</p>
                        <button className="w-full bg-white text-primary-600 font-black py-4 rounded-2xl text-xs uppercase tracking-widest relative z-10 shadow-lg active:scale-95 transition-all">
                            Explore Hub
                        </button>
                    </div>
                </div>
            </div>
        </div>
    )
}
